/// Bundled `adaptive/layer-decision.schema.json` payload: the canonical
/// LayerDecision contract, generated via schemars from
/// `meerkat_mob::adaptive::LayerDecision` (meerkat `schema` feature) — the
/// run_layer/finish tagged union with the full LayerPlan shape. This MUST stay
/// `serde_json::Value`-equal to meerkat's `layer_decision_schema()`; a mismatch
/// fails any adaptive-pack deploy/validate with `StaleAdaptiveSchema`.
/// Regenerate via `schemars::schema_for!(meerkat_mob::adaptive::LayerDecision)`
/// when the adaptive types change.
///
/// As of meerkat 0.7.1+ the `LayerProfile::inline` variant is a full
/// `{"$ref": "#/$defs/Profile"}` with a complete Profile `$def` — inline
/// profiles are validated STRUCTURALLY, not accepted as an opaque `true`. (The
/// `SchemaRef`/`AdaptiveValue` defs still use `anyOf`-with-`true` for genuinely
/// opaque slots.) Inline profiles remain gated by the pack policy's
/// `allow_inline_profiles`.
const ADAPTIVE_LAYER_DECISION_SCHEMA_JSON: &str =
    include_str!("adaptive_layer_decision.schema.json");
const EDITOR_INPUT_STEP_ID_PREFIX: &str = "input";
const EDITOR_INPUT_STEP_DEFAULT_TASK: &str = "Run the mobpack flow.";
/// Default watchdog for the blocking `rkat mob run` child process. Under
/// meerkat 0.7 `mob run` accepts no duration budget and blocks until the
/// flow run is terminal, so this local kill (deploy.max_duration when set,
/// this default otherwise) is the ONLY bound — and it is a hard process
/// kill that loses the in-memory run. Keep it generous: multi-step LLM
/// flows routinely run minutes.
const DEFAULT_DEPLOY_EXEC_TIMEOUT_MS: u64 = 600_000;
const DEPLOY_EXEC_TIMEOUT_GRACE_MS: u64 = 250;
const MOBPACK_DRAFT_STORE_ENV: &str = "META_FLOW_EDITOR_DRAFT_STORE";
pub(crate) const MOBPACK_DRAFT_STORE_FILENAME: &str = "meerkat-meta-flow-editor-drafts.json";
const EDITOR_SCHEMA_FIELD_TYPES: &[&str] = &[
    "string", "string[]", "number", "float", "int", "integer", "boolean", "bool", "enum", "bytes",
    "object",
];

static MOBPACK_DRAFT_STORE_LOCK: Mutex<()> = Mutex::new(());

/// Hold the draft store lock, so draft methods wait for the test that holds
/// it.
#[cfg(test)]
pub(crate) fn hold_draft_store_lock_for_test() -> std::sync::MutexGuard<'static, ()> {
    MOBPACK_DRAFT_STORE_LOCK
        .lock()
        .unwrap_or_else(std::sync::PoisonError::into_inner)
}

/// Hold the draft store lock for one read, check and write of the store.
/// Every draft call from every caller waits for it.
fn lock_draft_store() -> Result<DraftStoreLock, String> {
    let guard = MOBPACK_DRAFT_STORE_LOCK
        .lock()
        .map_err(|_| "mobpack draft store lock poisoned".to_string())?;
    #[cfg(test)]
    DRAFT_STORE_LOCK_HELD.with(|held| held.set(true));
    Ok(DraftStoreLock { _guard: guard })
}

/// The held draft store lock.
struct DraftStoreLock {
    _guard: std::sync::MutexGuard<'static, ()>,
}

#[cfg(test)]
impl Drop for DraftStoreLock {
    fn drop(&mut self) {
        DRAFT_STORE_LOCK_HELD.with(|held| held.set(false));
    }
}

#[cfg(test)]
std::thread_local! {
    /// Whether this thread holds the draft store lock.
    static DRAFT_STORE_LOCK_HELD: std::cell::Cell<bool> = const { std::cell::Cell::new(false) };
    /// The documents this thread validated: in all, and while it held the
    /// draft store lock.
    static VALIDATIONS: std::cell::Cell<(u64, u64)> = const { std::cell::Cell::new((0, 0)) };
}

/// Counts one document validation for the tests. Outside tests it does
/// nothing.
fn count_validation() {
    #[cfg(test)]
    VALIDATIONS.with(|count| {
        let (all, under_lock) = count.get();
        let locked = DRAFT_STORE_LOCK_HELD.with(std::cell::Cell::get);
        count.set((all + 1, under_lock + u64::from(locked)));
    });
}

