fn editor_adaptive_limit_defaults() -> Value {
    let mut limits = serde_json::Map::new();
    for (camel_key, _, default, _, _) in EDITOR_ADAPTIVE_LIMITS {
        limits.insert((*camel_key).to_string(), Value::from(*default));
    }
    Value::Object(limits)
}

