pub fn runtime_flow_registry_rows_from_definition(definition: &MobDefinition) -> Vec<Value> {
    definition
        .flows
        .keys()
        .filter_map(|flow_id| {
            runtime_flow_registry_row_from_definition(definition, flow_id.as_ref()).ok()
        })
        .collect()
}

fn runtime_flow_registry_row_from_definition(
    definition: &MobDefinition,
    flow_id: &str,
) -> Result<Value, String> {
    let flow_id = flow_id.trim();
    if flow_id.is_empty() {
        return Err("runtime flow id is empty".to_string());
    }
    let mob_id = definition.id.to_string();
    let name = if definition.flows.len() > 1 {
        format!("{mob_id} · {flow_id}")
    } else {
        mob_id.clone()
    };
    let mut document = project_definition_to_editor_document_for_flow(
        definition,
        "",
        Some(&name),
        Value::Null,
        Some(flow_id),
    )?;
    document.mob_toml = None;
    let validation = validate_document(&document);
    let validation_value = serde_json::to_value(&validation).unwrap_or(Value::Null);
    Ok(json!({
        "id": format!(
            "runtime_{}_{}",
            sanitize_identifier(&mob_id),
            sanitize_identifier(flow_id)
        ),
        "name": name,
        "version": MOBPACK_SCHEMA_VERSION,
        "stage": if validation.ok { "valid" } else { "draft" },
        "trigger": format!("runtime · {flow_id}"),
        "source": "meta/runtime/flow_projection",
        "registry_source": "meta/runtime/flow_projection",
        "document_kind": "runtime_projection",
        "runtime_projection": true,
        "runtime_mob_id": mob_id,
        "runtime_flow_id": flow_id,
        "document": document,
        "validation": validation_value,
        "deployability": catalog_deployability(
            validation.ok,
            "runtime flow projection can be exported as a deployable single-flow Meta mobpack draft"
        ),
        "provenance": catalog_provenance(
            "meta/runtime/flow_projection",
            "UnifiedRuntime.MobDefinition",
            &format!("{mob_id}:flows.{flow_id}")
        ),
    }))
}

fn sample_mobpack_catalog() -> Value {
    let samples = [
        (
            "sample_planner_coder_review_loop",
            "planner-coder-reviewer",
            "label · small-fix",
            sample_planner_coder_review_loop_toml(),
        ),
        (
            "sample_docs_only",
            "docs-only",
            "path · docs/**",
            sample_docs_only_toml(),
        ),
        (
            "sample_review_pr",
            "review-pr",
            "kind · pull_request",
            sample_review_pr_toml(),
        ),
    ];
    Value::Array(
        samples
            .into_iter()
            .filter_map(|(id, name, trigger, mob_toml)| {
                let definition = MobDefinition::from_toml(mob_toml).ok()?;
                let document = project_definition_to_editor_document(
                    &definition,
                    mob_toml,
                    Some(name),
                    Value::Null,
                )
                .ok()?;
                let validation = validate_document(&document);
                Some(json!({
                    "id": id,
                    "name": name,
                    "version": MOBPACK_SCHEMA_VERSION,
                    "stage": if validation.ok { "valid" } else { "draft" },
                    "trigger": trigger,
                    "source": "meta/sample-mobpack",
                    "deployability": catalog_deployability(validation.ok, "sample mobpack template validates as a deployable Meta mobpack"),
                    "provenance": catalog_provenance("meta/mobpacks/templates", "meta/sample-mobpack", id),
                    "document": document,
                    "validation": validation,
                }))
            })
            .collect(),
    )
}

