pub fn import_mobpack(params: &Value) -> Result<Value, String> {
    let mut document = document_from_params(params)?;
    if document.mob_toml.as_deref().unwrap_or("").trim().is_empty()
        && let Some(text) = params.get("mob_toml").and_then(Value::as_str)
    {
        document.mob_toml = Some(text.to_string());
    }
    if needs_editor_projection(&document)
        && let Some(mob_toml) = document
            .mob_toml
            .as_deref()
            .map(str::trim)
            .filter(|text| !text.is_empty())
    {
        let definition = MobDefinition::from_toml(mob_toml)
            .map_err(|err| format!("failed to parse mob.toml for editor import: {err}"))?;
        if definition.flows.len() > 1 {
            return Err(format!(
                "cannot import mob.toml into Flow Editor: {} flows found, but this editor projection supports exactly one flow; export/deploy the original mob.toml directly or split it into a single-flow mobpack",
                definition.flows.len()
            ));
        }
        document = project_definition_to_editor_document(
            &definition,
            mob_toml,
            (!document.name.trim().is_empty()).then_some(document.name.as_str()),
            document.deploy.clone(),
        )?;
    }
    let validation = validate_document(&document);
    if let Some(diagnostic) = validation
        .diagnostics
        .iter()
        .find(|diagnostic| is_starter_provenance_diagnostic(&diagnostic.code))
    {
        return Err(format!(
            "cannot import prototype starter skill data: {} at {}",
            diagnostic.code,
            diagnostic.path.as_deref().unwrap_or("skill_realms")
        ));
    }
    let source = import_source_from_params(params);
    Ok(json!({
        "document": document,
        "validation": validation,
        "source": source.source,
        "source_label": source.label,
        "source_media_type": source.media_type,
    }))
}

struct MobpackImportSource {
    source: &'static str,
    label: String,
    media_type: String,
}

fn import_source_from_params(params: &Value) -> MobpackImportSource {
    let label = params
        .get("source_name")
        .or_else(|| params.get("filename"))
        .and_then(Value::as_str)
        .map(str::trim)
        .filter(|value| !value.is_empty());
    if params
        .get("content_base64")
        .and_then(Value::as_str)
        .is_some()
    {
        return MobpackImportSource {
            source: "meta/mobpacks/import:archive",
            label: label.unwrap_or("mobpack archive").to_string(),
            media_type: import_media_type(params, "application/vnd.meerkat.mobpack"),
        };
    }
    if params.get("mob_toml").and_then(Value::as_str).is_some() {
        return MobpackImportSource {
            source: "meta/mobpacks/import:mob.toml",
            label: label.unwrap_or("mob.toml").to_string(),
            media_type: import_media_type(params, "text/x-toml"),
        };
    }
    if params.get("document").is_some() {
        return MobpackImportSource {
            source: "meta/mobpacks/import:editor-document",
            label: label.unwrap_or("meta/editor.json").to_string(),
            media_type: import_media_type(params, "application/json"),
        };
    }
    MobpackImportSource {
        source: "meta/mobpacks/import:document",
        label: label.unwrap_or("mobpack document").to_string(),
        media_type: import_media_type(params, "application/json"),
    }
}

fn import_media_type(params: &Value, fallback: &str) -> String {
    params
        .get("source_media_type")
        .and_then(Value::as_str)
        .map(str::trim)
        .filter(|value| !value.is_empty())
        .unwrap_or(fallback)
        .to_string()
}

/// The draft store `META_FLOW_EDITOR_DRAFT_STORE` names, when it names one:
/// the store a draft request that names no `store_path` uses.
pub(crate) fn env_draft_store_path() -> Option<PathBuf> {
    std::env::var(MOBPACK_DRAFT_STORE_ENV)
        .ok()
        .map(|value| value.trim().to_string())
        .filter(|value| !value.is_empty())
        .map(PathBuf::from)
}

fn mobpack_draft_store_path(params: &Value) -> Result<PathBuf, DraftStoreRefusal> {
    let explicit = params
        .get("store_path")
        .and_then(Value::as_str)
        .map(str::trim)
        .filter(|value| !value.is_empty())
        .map(PathBuf::from)
        .or_else(env_draft_store_path);
    match explicit {
        Some(path) => Ok(path),
        None => default_mobpack_draft_store_path(),
    }
}

fn default_mobpack_draft_store_path() -> Result<PathBuf, DraftStoreRefusal> {
    // The draft store lives under the gateway home; the ambient
    // `$XDG_STATE_HOME`/`$HOME` derivation belongs to `storage_layout`
    // (M5 gate), never re-read here. Without either root the store has no
    // location and refuses: a file at a predictable path in the shared OS
    // temp directory could be created, linked or read first by another local
    // user. An unadopted predecessor home refuses too: its drafts exist, so
    // the store does not start empty elsewhere.
    match crate::storage_layout::default_gateway_home() {
        Ok(home) => Ok(home.join(MOBPACK_DRAFT_STORE_FILENAME)),
        Err(crate::storage_layout::StorageLayoutError::GatewayHomeUnavailable) => {
            Err(DraftStoreRefusal::NoStateRoot)
        }
        Err(error) => Err(DraftStoreRefusal::GatewayHome(error)),
    }
}

/// Why the Flow Editor draft store refused a call. A JSON-RPC caller gets it
/// as the error `data` ([`DraftStoreRefusal::data`]): a `kind` and the fields
/// that kind names.
#[derive(Debug, Clone, PartialEq, Eq)]
pub(crate) enum DraftStoreRefusal {
    /// No `META_FLOW_EDITOR_DRAFT_STORE`, and neither `$XDG_STATE_HOME` nor
    /// `$HOME` to derive the gateway home from: the store has no location.
    NoStateRoot,
    /// The gateway home cannot hold the store yet: its predecessor (pre-0.9)
    /// home waits for adoption.
    GatewayHome(crate::storage_layout::StorageLayoutError),
    /// The store holds [`MOBPACK_DRAFT_STORE_MAX_DRAFTS`] drafts: a new one
    /// would pass the cap.
    TooManyDrafts,
    /// The store file would pass [`MOBPACK_DRAFT_STORE_MAX_BYTES`] even with
    /// every undo and redo snapshot dropped: it would take `required_bytes`.
    TooLarge { required_bytes: usize },
    /// The store file holds `bytes`, past
    /// [`MOBPACK_DRAFT_STORE_MAX_READ_BYTES`] (a store written before the
    /// caps): it is refused before it is read.
    Oversized { bytes: u64, path: PathBuf },
}

impl DraftStoreRefusal {
    /// The JSON-RPC error `data`.
    fn data(&self) -> Value {
        match self {
            Self::NoStateRoot => json!({
                "kind": "draft_store_unavailable",
                "reason": "gateway_home_unavailable",
            }),
            Self::GatewayHome(error) => json!({
                "kind": "draft_store_unavailable",
                "reason": match error {
                    crate::storage_layout::StorageLayoutError::PredecessorGatewayHome { .. } => {
                        "predecessor_gateway_home"
                    }
                    crate::storage_layout::StorageLayoutError::AdoptionIncomplete { .. } => {
                        "adoption_incomplete"
                    }
                    _ => "gateway_home_refused",
                },
            }),
            Self::TooManyDrafts => json!({
                "kind": "draft_store_full",
                "limit": "drafts",
                "max_drafts": MOBPACK_DRAFT_STORE_MAX_DRAFTS,
            }),
            Self::TooLarge { required_bytes } => json!({
                "kind": "draft_store_full",
                "limit": "bytes",
                "max_bytes": MOBPACK_DRAFT_STORE_MAX_BYTES,
                "required_bytes": required_bytes,
            }),
            Self::Oversized { bytes, .. } => json!({
                "kind": "draft_store_unavailable",
                "reason": "store_too_large",
                "max_read_bytes": MOBPACK_DRAFT_STORE_MAX_READ_BYTES,
                "store_bytes": bytes,
            }),
        }
    }

    fn message(&self) -> String {
        match self {
            Self::NoStateRoot => "the Flow Editor draft store has no location: neither \
                                  XDG_STATE_HOME nor HOME is set, and drafts are never kept in \
                                  the shared temp directory; set META_FLOW_EDITOR_DRAFT_STORE to \
                                  a file in a directory only this user can write, or set \
                                  XDG_STATE_HOME or HOME"
                .to_string(),
            Self::GatewayHome(error) if host_access() => error.to_string(),
            Self::GatewayHome(_) => "the Flow Editor draft store is unavailable until the host \
                                   finishes adopting its predecessor (pre-0.9) state"
                .to_string(),
            Self::TooManyDrafts => format!(
                "the Flow Editor draft store holds at most {MOBPACK_DRAFT_STORE_MAX_DRAFTS} drafts; \
                 delete a draft to save a new one"
            ),
            Self::TooLarge { required_bytes } => format!(
                "the Flow Editor draft store holds at most {} MiB, and this save needs \
                 {required_bytes} bytes even without undo history; delete drafts to make room",
                MOBPACK_DRAFT_STORE_MAX_BYTES >> 20
            ),
            Self::Oversized { bytes, path } => format!(
                "the {} holds {bytes} bytes, more than {} MiB, and is not read; move it aside \
                 to start a new draft store",
                draft_store_name(path),
                MOBPACK_DRAFT_STORE_MAX_READ_BYTES >> 20
            ),
        }
    }
}

/// A draft store method's failure, as its JSON-RPC error reports it: the
/// message, and for a typed refusal the error `data`.
#[derive(Debug, Clone)]
pub(crate) struct DraftStoreFailure {
    pub(crate) message: String,
    pub(crate) data: Option<Value>,
}

impl From<String> for DraftStoreFailure {
    fn from(message: String) -> Self {
        Self {
            message,
            data: None,
        }
    }
}

impl From<DraftStoreRefusal> for DraftStoreFailure {
    fn from(refusal: DraftStoreRefusal) -> Self {
        Self {
            message: refusal.message(),
            data: Some(refusal.data()),
        }
    }
}

/// The draft store methods for the JSON-RPC dispatch, reporting typed
/// refusals; `None` for any other method.
pub(crate) fn mobpack_draft_store_method(
    method: &str,
    params: &Value,
    runtime: Option<&MobpackRuntimeCatalogState>,
) -> Option<Result<Value, DraftStoreFailure>> {
    Some(match method {
        "meta/mobpacks/list" => list_drafts(params, runtime),
        "meta/mobpacks/get" => get_draft(params, runtime),
        "meta/mobpacks/create" => create_draft(params),
        "meta/mobpacks/save" => save_draft(params),
        "meta/mobpacks/delete" => delete_draft(params),
        "meta/mobpacks/undo" => step_mobpack_draft_history(params, MobpackDraftHistoryStep::Undo),
        "meta/mobpacks/redo" => step_mobpack_draft_history(params, MobpackDraftHistoryStep::Redo),
        _ => return None,
    })
}

/// A draft store reply: `reply`, naming the store's host path as `store_path`
/// only to a caller with host access ([`host_access`]). Any other caller is
/// not told where the host keeps it.
fn draft_store_reply(mut reply: Value, path: &Path) -> Value {
    if host_access() {
        reply["store_path"] = json!(path);
    }
    reply
}

/// The reply of a draft store write ([`draft_store_reply`]). A write that
/// replaced the store but could not sync its directory has taken effect, so
/// its reply carries the written draft as any other does, with the warning
/// as `durability_warning`.
fn draft_store_write_reply(reply: Value, path: &Path, durability_warning: Option<String>) -> Value {
    let mut reply = draft_store_reply(reply, path);
    if let Some(warning) = durability_warning {
        reply["durability_warning"] = json!(warning);
    }
    reply
}

/// The draft store as a message names it: by its host path for a caller with
/// host access ([`host_access`]), without one for any other caller.
fn draft_store_name(path: &Path) -> String {
    if host_access() {
        format!("mobpack draft store {}", path.display())
    } else {
        "mobpack draft store".to_string()
    }
}

/// The most drafts the Flow Editor draft store holds.
const MOBPACK_DRAFT_STORE_MAX_DRAFTS: usize = 256;

/// The most bytes the draft store file holds. Every draft method reads and
/// parses the whole store, so this bounds what one call holds in memory as
/// well as the disk the store takes.
const MOBPACK_DRAFT_STORE_MAX_BYTES: usize = 64 * 1024 * 1024;

/// The most bytes of a draft store file the draft methods read: twice
/// [`MOBPACK_DRAFT_STORE_MAX_BYTES`]. A store written before the caps can be
/// past the cap and still works, but one past this is refused before it is
/// read, since every draft method reads and parses the whole file.
const MOBPACK_DRAFT_STORE_MAX_READ_BYTES: u64 = 2 * MOBPACK_DRAFT_STORE_MAX_BYTES as u64;

/// How many drafts and bytes the draft store file held when it was read.
#[derive(Clone, Copy)]
struct DraftStoreSize {
    drafts: usize,
    bytes: usize,
}

fn read_mobpack_draft_store(path: &Path) -> Result<BTreeMap<String, Value>, String> {
    read_draft_store(path)
        .map(|(rows, _)| rows)
        .map_err(|failure| failure.message)
}

/// The draft store's rows, and its size as read. A missing or empty file is an
/// empty store; a file past [`MOBPACK_DRAFT_STORE_MAX_READ_BYTES`] is refused
/// before any of it is read.
fn read_draft_store(
    path: &Path,
) -> Result<(BTreeMap<String, Value>, DraftStoreSize), DraftStoreFailure> {
    let empty = DraftStoreSize {
        drafts: 0,
        bytes: 0,
    };
    let unreadable =
        |err: std::io::Error| format!("failed to read {}: {err}", draft_store_name(path));
    let oversized = |bytes: u64| DraftStoreRefusal::Oversized {
        bytes,
        path: path.to_path_buf(),
    };
    let file = match std::fs::File::open(path) {
        Ok(file) => file,
        Err(err) if err.kind() == std::io::ErrorKind::NotFound => {
            return Ok((BTreeMap::new(), empty));
        }
        Err(err) => return Err(unreadable(err).into()),
    };
    let len = file.metadata().map_err(unreadable)?.len();
    if len > MOBPACK_DRAFT_STORE_MAX_READ_BYTES {
        return Err(oversized(len).into());
    }
    let mut bytes = Vec::new();
    file.take(MOBPACK_DRAFT_STORE_MAX_READ_BYTES.saturating_add(1))
        .read_to_end(&mut bytes)
        .map_err(unreadable)?;
    let read = u64::try_from(bytes.len()).unwrap_or(u64::MAX);
    if read > MOBPACK_DRAFT_STORE_MAX_READ_BYTES {
        return Err(oversized(read).into());
    }
    if bytes.is_empty() {
        return Ok((BTreeMap::new(), empty));
    }
    let rows: BTreeMap<String, Value> = serde_json::from_slice(&bytes)
        .map_err(|err| format!("failed to parse {}: {err}", draft_store_name(path)))?;
    let size = DraftStoreSize {
        drafts: rows.len(),
        bytes: bytes.len(),
    };
    Ok((rows, size))
}

/// Write the draft store: streamed into a new file beside it, readable only
/// by its user, synced to disk, then renamed over it, and the directory
/// synced after the rename, so a crash leaves either the old store or the
/// new one whole. Each write gets a file of its own, so writers that share a
/// store never write into one temporary file, and the store is never encoded
/// into memory first.
///
/// Once renamed, the store holds the write: a directory that cannot be
/// synced then is returned as a durability warning for the write's reply
/// ([`draft_store_write_reply`]), never as its failure. Undo and redo are
/// not idempotent, so a client that retried a write reported failed would
/// step the draft twice.
fn write_mobpack_draft_store(
    path: &Path,
    rows: &BTreeMap<String, Value>,
) -> Result<Option<String>, String> {
    let dir = match path.parent() {
        Some(parent) if !parent.as_os_str().is_empty() => parent,
        _ => Path::new("."),
    };
    create_private_dir_all(dir).map_err(|err| {
        format!(
            "failed to create the directory of {}: {err}",
            draft_store_name(path)
        )
    })?;
    let unwritable =
        |err: std::io::Error| format!("failed to write {}: {err}", draft_store_name(path));
    let mut file = tempfile::Builder::new()
        .prefix(".flow-editor-drafts-")
        .suffix(".tmp")
        .tempfile_in(dir)
        .map_err(unwritable)?;
    let mut writer = std::io::BufWriter::new(file.as_file_mut());
    serde_json::to_writer_pretty(&mut writer, rows)
        .map_err(|err| format!("failed to encode {}: {err}", draft_store_name(path)))?;
    writer.flush().map_err(unwritable)?;
    drop(writer);
    file.as_file().sync_all().map_err(unwritable)?;
    file.persist(path).map_err(|err| {
        format!(
            "failed to replace {}: {}",
            draft_store_name(path),
            err.error
        )
    })?;
    Ok(sync_dir(dir).err().map(|err| {
        tracing::warn!(
            store = %path.display(),
            error = %err,
            "the Flow Editor draft store was replaced, but its directory could not be synced"
        );
        format!(
            "{} was replaced, but its directory could not be synced, so the write may not survive a crash: {err}",
            draft_store_name(path)
        )
    }))
}

#[cfg(test)]
std::thread_local! {
    /// Fails the next directory sync on this thread, for the tests of a
    /// store write whose directory cannot be synced.
    static FAIL_NEXT_DIR_SYNC: std::cell::Cell<bool> = const { std::cell::Cell::new(false) };
}

/// Sync a directory's entries to disk, so a rename into it survives a crash.
/// A directory this user cannot open, or one its filesystem cannot sync, is
/// left as it is: the rename lasts as long as the filesystem keeps it.
#[cfg(unix)]
fn sync_dir(dir: &Path) -> std::io::Result<()> {
    use std::io::ErrorKind;
    #[cfg(test)]
    if FAIL_NEXT_DIR_SYNC.with(std::cell::Cell::take) {
        return Err(std::io::Error::other("injected directory sync failure"));
    }
    match std::fs::File::open(dir).and_then(|dir| dir.sync_all()) {
        Err(err)
            if !matches!(
                err.kind(),
                ErrorKind::PermissionDenied | ErrorKind::InvalidInput | ErrorKind::Unsupported
            ) =>
        {
            Err(err)
        }
        _ => Ok(()),
    }
}

#[cfg(not(unix))]
fn sync_dir(_dir: &Path) -> std::io::Result<()> {
    Ok(())
}

/// Create `dir` and any missing parent, readable only by this user; a
/// directory that exists keeps its mode.
#[cfg(unix)]
fn create_private_dir_all(dir: &Path) -> std::io::Result<()> {
    use std::os::unix::fs::DirBuilderExt;
    std::fs::DirBuilder::new()
        .recursive(true)
        .mode(0o700)
        .create(dir)
}

#[cfg(not(unix))]
fn create_private_dir_all(dir: &Path) -> std::io::Result<()> {
    std::fs::create_dir_all(dir)
}

/// Check `rows`, the store after a write to the draft `id`, against the store
/// caps; `before` is the store as that write read it. Sizes are counted, not
/// encoded, so checking a store near the byte cap builds no copy of it.
///
/// A write that adds a draft past [`MOBPACK_DRAFT_STORE_MAX_DRAFTS`] is
/// refused. Past [`MOBPACK_DRAFT_STORE_MAX_BYTES`] undo and redo history yields
/// first: the oldest snapshots go, of the drafts updated longest ago first and
/// of the written draft last, until the store fits. With no snapshot left the
/// write is refused and the store keeps what it held. A store already past a
/// cap (written before the caps) still takes writes that leave it no larger.
fn admit_draft_store_write(
    rows: &mut BTreeMap<String, Value>,
    id: &str,
    before: DraftStoreSize,
) -> Result<(), DraftStoreFailure> {
    if rows.len() > MOBPACK_DRAFT_STORE_MAX_DRAFTS && rows.len() > before.drafts {
        return Err(DraftStoreRefusal::TooManyDrafts.into());
    }
    let limit = MOBPACK_DRAFT_STORE_MAX_BYTES.max(before.bytes);
    let size = draft_store_len(rows);
    if size <= limit {
        return Ok(());
    }
    // A snapshot's pretty-printed bytes are at least its compact JSON, so
    // dropping snapshots whose compact JSON covers the excess shrinks the file
    // to the limit.
    let mut excess = size - limit;
    for draft in draft_history_yield_order(rows, id) {
        let Some(row) = rows.get_mut(&draft).and_then(Value::as_object_mut) else {
            continue;
        };
        for key in ["history", "future"] {
            let Some(snapshots) = row.get_mut(key).and_then(Value::as_array_mut) else {
                continue;
            };
            while excess > 0 && !snapshots.is_empty() {
                excess = excess.saturating_sub(compact_json_len(&snapshots.remove(0)));
            }
        }
        if excess == 0 {
            break;
        }
    }
    let size = draft_store_len(rows);
    if size <= limit {
        Ok(())
    } else {
        Err(DraftStoreRefusal::TooLarge {
            required_bytes: size,
        }
        .into())
    }
}

/// The drafts in the order their undo and redo history yields to a write:
/// the drafts updated longest ago first, the written draft `id` last.
fn draft_history_yield_order(rows: &BTreeMap<String, Value>, id: &str) -> Vec<String> {
    let mut others = rows
        .iter()
        .filter(|(draft, _)| draft.as_str() != id)
        .map(|(draft, row)| {
            (
                row.get("updated_at_unix_ms")
                    .and_then(Value::as_u64)
                    .unwrap_or(0),
                draft.clone(),
            )
        })
        .collect::<Vec<_>>();
    others.sort();
    others
        .into_iter()
        .map(|(_, draft)| draft)
        .chain(std::iter::once(id.to_string()))
        .collect()
}

/// Counts the bytes written to it, so an encoding's size is known without
/// building it.
struct JsonByteCounter(usize);

impl std::io::Write for JsonByteCounter {
    fn write(&mut self, bytes: &[u8]) -> std::io::Result<usize> {
        self.0 = self.0.saturating_add(bytes.len());
        Ok(bytes.len())
    }

    fn flush(&mut self) -> std::io::Result<()> {
        Ok(())
    }
}

/// How many bytes `value` takes as compact JSON, counted without building it.
fn compact_json_len(value: &Value) -> usize {
    let mut counter = JsonByteCounter(0);
    serde_json::to_writer(&mut counter, value).map_or(0, |()| counter.0)
}

/// How many bytes the draft store takes as it is written (pretty JSON),
/// counted without building it.
fn draft_store_len(rows: &BTreeMap<String, Value>) -> usize {
    let mut counter = JsonByteCounter(0);
    serde_json::to_writer_pretty(&mut counter, rows).map_or(0, |()| counter.0)
}

/// The most characters of a draft's id. A draft summary carries its id
/// whole.
const MOBPACK_DRAFT_MAX_ID_CHARS: usize = 256;

fn mobpack_draft_id_from_params(
    params: &Value,
    document: &MobpackDocument,
) -> Result<String, String> {
    let id = params
        .get("id")
        .and_then(Value::as_str)
        .map(str::trim)
        .filter(|value| !value.is_empty())
        .map(ToString::to_string)
        .or_else(|| {
            (!document.mob_id.trim().is_empty())
                .then(|| sanitize_identifier(document.mob_id.trim()))
        })
        .or_else(|| {
            (!document.name.trim().is_empty()).then(|| sanitize_identifier(document.name.trim()))
        })
        .filter(|value| !value.is_empty())
        .ok_or_else(|| "meta/mobpacks/save requires id or document.mob_id".to_string())?;
    let chars = id.chars().count();
    if chars > MOBPACK_DRAFT_MAX_ID_CHARS {
        return Err(format!(
            "mobpack draft id has {chars} characters, more than {MOBPACK_DRAFT_MAX_ID_CHARS}"
        ));
    }
    Ok(id)
}

fn mobpack_draft_revision_from_row(row: Option<&Value>) -> u64 {
    row.and_then(|value| {
        value
            .get("revision")
            .or_else(|| value.get("draft_revision"))
            .and_then(Value::as_u64)
    })
    .unwrap_or(0)
}

fn mobpack_draft_expected_revision(params: &Value) -> Option<u64> {
    [
        "expected_revision",
        "expectedRevision",
        "base_revision",
        "baseRevision",
        "if_revision",
        "ifRevision",
    ]
    .iter()
    .find_map(|key| params.get(*key).and_then(Value::as_u64))
}

fn mobpack_draft_etag(id: &str, revision: u64) -> String {
    format!("{id}:{revision}")
}

fn mobpack_draft_expected_etag(params: &Value) -> Option<String> {
    [
        "expected_etag",
        "expectedEtag",
        "if_match",
        "ifMatch",
        "draft_etag",
        "etag",
    ]
    .iter()
    .find_map(|key| {
        params
            .get(*key)
            .and_then(Value::as_str)
            .map(str::trim)
            .filter(|value| !value.is_empty())
            .map(ToString::to_string)
    })
}

fn mobpack_draft_guard_id(params: &Value) -> Option<String> {
    [
        "id",
        "currentFlowId",
        "current_flow_id",
        "draft_id",
        "draftId",
    ]
    .iter()
    .find_map(|key| {
        params
            .get(*key)
            .and_then(Value::as_str)
            .map(str::trim)
            .filter(|value| !value.is_empty())
            .map(ToString::to_string)
    })
}

fn enforce_mobpack_draft_expected_revision(params: &Value, source: &str) -> Result<(), String> {
    let expected_revision = mobpack_draft_expected_revision(params);
    let expected_etag = mobpack_draft_expected_etag(params);
    if expected_revision.is_none() && expected_etag.is_none() {
        return Ok(());
    }
    let id = mobpack_draft_guard_id(params)
        .ok_or_else(|| format!("{source} expected revision/etag requires draft id"))?;
    let _guard = lock_draft_store()?;
    let path = mobpack_draft_store_path(params).map_err(|refusal| refusal.message())?;
    let rows = read_mobpack_draft_store(&path)?;
    let existing = rows.get(&id);
    let current_revision = mobpack_draft_revision_from_row(existing);
    if let Some(expected_revision) = expected_revision
        && expected_revision != current_revision
    {
        return Err(format!(
            "{source} draft revision conflict for {id}: expected {expected_revision}, found {current_revision}"
        ));
    }
    if let Some(expected_etag) = expected_etag {
        let current_etag = mobpack_draft_etag(&id, current_revision);
        if expected_etag != current_etag {
            return Err(format!(
                "{source} draft etag conflict for {id}: expected {expected_etag}, found {current_etag}"
            ));
        }
    }
    Ok(())
}

/// Stamp a draft row, built before the store was locked, with the revision
/// it is stored at.
fn set_draft_row_revision(row: &mut Value, id: &str, revision: u64) {
    let etag = mobpack_draft_etag(id, revision);
    row["revision"] = json!(revision);
    row["draft_revision"] = json!(revision);
    row["etag"] = json!(etag);
    row["draft_etag"] = json!(etag);
}

fn mobpack_draft_row_from_params(params: &Value, revision: u64) -> Result<Value, String> {
    let mut document = document_from_params(params)?;
    let id = mobpack_draft_id_from_params(params, &document)?;
    let draft_etag = mobpack_draft_etag(&id, revision);
    let validation_result = canonicalize_deployable_authoring_document(&mut document)?;
    let validation = serde_json::to_value(&validation_result).unwrap_or(Value::Null);
    let stage = if validation.get("ok").and_then(Value::as_bool) == Some(true) {
        "valid".to_string()
    } else {
        "draft".to_string()
    };
    let trigger = params
        .get("trigger")
        .and_then(Value::as_str)
        .map(str::trim)
        .filter(|value| !value.is_empty())
        .map(ToString::to_string)
        .or_else(|| {
            document
                .flow
                .get("description")
                .and_then(Value::as_str)
                .map(str::trim)
                .filter(|value| !value.is_empty())
                .map(ToString::to_string)
        })
        .unwrap_or_else(|| "Meta authoring draft".to_string());
    let source = params
        .get("source")
        .and_then(Value::as_str)
        .map(str::trim)
        .filter(|value| !value.is_empty())
        .unwrap_or("meta/mobpacks/save");
    let updated_at_unix_ms = SystemTime::now()
        .duration_since(UNIX_EPOCH)
        .map(|duration| duration.as_millis() as u64)
        .unwrap_or(0);
    let artifact = mobpack_registry_artifact_for_document(&document, &validation);
    Ok(json!({
        "id": id,
        "name": if document.name.trim().is_empty() { document.mob_id.clone() } else { document.name.clone() },
        "version": document.schema_version,
        "stage": stage,
        "trigger": trigger,
        "source": source,
        "document_kind": "editor_projection",
        "document": document,
        "artifact": artifact,
        "validation": validation,
        "updated_at_unix_ms": updated_at_unix_ms,
        "registry_source": "meta/mobpacks/save",
        "revision": revision,
        "draft_revision": revision,
        "etag": draft_etag,
        "draft_etag": draft_etag
    }))
}

fn mobpack_registry_artifact_for_document(document: &MobpackDocument, validation: &Value) -> Value {
    if validation.get("ok").and_then(Value::as_bool) != Some(true) {
        return json!({
            "kind": "editor_draft",
            "deployable": false,
            "reason": "validation_failed",
            "source": "meta/mobpacks/save"
        });
    }
    match export_mobpack(&json!({ "document": document })) {
        Ok(export) => {
            let pack_sha256 = base64::engine::general_purpose::STANDARD
                .decode(export.content_base64.as_bytes())
                .ok()
                .map(|bytes| source_file_sha256(&bytes))
                .unwrap_or_default();
            json!({
                "kind": "mobpack_archive",
                "deployable": true,
                "source": "meta/mobpacks/export",
                "filename": export.filename,
                "media_type": export.media_type,
                "content_base64": export.content_base64,
                "pack_sha256": pack_sha256,
                "mob_toml": export.mob_toml,
                "source_files": export.source_files,
                "validation": export.validation
            })
        }
        Err(error) => json!({
            "kind": "editor_draft",
            "deployable": false,
            "reason": "export_failed",
            "error": error,
            "source": "meta/mobpacks/save"
        }),
    }
}

fn mobpack_draft_template(template_id: &str) -> Result<Value, String> {
    let template = if template_id == "blank" || template_id.trim().is_empty() {
        blank_mobpack_template()
    } else {
        sample_mobpack_catalog()
            .as_array()
            .and_then(|samples| {
                samples
                    .iter()
                    .find(|sample| sample["id"].as_str() == Some(template_id))
                    .cloned()
            })
            .unwrap_or(Value::Null)
    };
    if template.is_null() {
        return Err(format!(
            "meta/mobpacks/create unknown template: {template_id}"
        ));
    }
    Ok(template)
}

fn clone_draft_template_document(template: &Value, name: &str) -> Result<MobpackDocument, String> {
    let mut document = document_from_value(
        template
            .get("document")
            .ok_or_else(|| "meta/mobpacks/create template is missing document".to_string())?,
    )?;
    let clean_name = name.trim();
    if !clean_name.is_empty() {
        document.name = clean_name.to_string();
        document.mob_id = sanitize_identifier(clean_name);
        if let Some(flow) = document.flow.as_object_mut() {
            flow.insert("name".to_string(), Value::String(clean_name.to_string()));
        }
    }
    document.mob_toml = None;
    Ok(document)
}

fn mobpack_create_draft_id(
    params: &Value,
    document: &MobpackDocument,
    rows: &BTreeMap<String, Value>,
) -> String {
    if let Some(id) = params
        .get("id")
        .and_then(Value::as_str)
        .map(str::trim)
        .filter(|value| !value.is_empty())
    {
        return id.to_string();
    }
    let base = params
        .get("name")
        .and_then(Value::as_str)
        .map(str::trim)
        .filter(|value| !value.is_empty())
        .or_else(|| (!document.name.trim().is_empty()).then_some(document.name.trim()))
        .or_else(|| {
            params
                .get("template")
                .and_then(Value::as_str)
                .map(str::trim)
                .filter(|value| !value.is_empty())
        })
        .unwrap_or("meta_flow");
    let clean = sanitize_identifier(base);
    let prefix = if clean.starts_with("f_") {
        clean
    } else {
        format!("f_{clean}")
    };
    if !rows.contains_key(&prefix) {
        return prefix;
    }
    let mut index = 2;
    loop {
        let candidate = format!("{prefix}_{index}");
        if !rows.contains_key(&candidate) {
            return candidate;
        }
        index += 1;
    }
}

pub fn create_mobpack_draft(params: &Value) -> Result<Value, String> {
    create_draft(params).map_err(|failure| failure.message)
}

fn create_draft(params: &Value) -> Result<Value, DraftStoreFailure> {
    let template_id = params
        .get("template")
        .and_then(Value::as_str)
        .map(str::trim)
        .filter(|value| !value.is_empty())
        .unwrap_or("blank");
    let template = mobpack_draft_template(template_id)?;
    let fallback_name = template
        .get("name")
        .and_then(Value::as_str)
        .unwrap_or("Meta Flow");
    let name = params
        .get("name")
        .and_then(Value::as_str)
        .map(str::trim)
        .filter(|value| !value.is_empty())
        .unwrap_or(fallback_name);
    let document = clone_draft_template_document(&template, name)?;
    let path = mobpack_draft_store_path(params)?;
    let validation = validate_document(&document);
    let trigger = params
        .get("trigger")
        .and_then(Value::as_str)
        .map(str::trim)
        .filter(|value| !value.is_empty())
        .or_else(|| template.get("trigger").and_then(Value::as_str))
        .unwrap_or("Meta authoring draft");
    let source = template
        .get("source")
        .and_then(Value::as_str)
        .unwrap_or("meta/mobpacks/create");
    let updated_at_unix_ms = SystemTime::now()
        .duration_since(UNIX_EPOCH)
        .map(|duration| duration.as_millis() as u64)
        .unwrap_or(0);
    let validation_value = serde_json::to_value(&validation).unwrap_or(Value::Null);
    // Exported before the store is locked: the lock covers only the store's
    // read, checks and write.
    let artifact = mobpack_registry_artifact_for_document(&document, &validation_value);
    let lock = lock_draft_store()?;
    let (mut rows, before) = read_draft_store(&path)?;
    let id = mobpack_create_draft_id(params, &document, &rows);
    if !rows.contains_key(&id) && rows.len() >= MOBPACK_DRAFT_STORE_MAX_DRAFTS {
        return Err(DraftStoreRefusal::TooManyDrafts.into());
    }
    let revision = 1_u64;
    let draft_etag = mobpack_draft_etag(&id, revision);
    let row = json!({
        "id": id,
        "name": if document.name.trim().is_empty() { &document.mob_id } else { &document.name },
        "version": document.schema_version,
        "stage": "draft",
        "trigger": trigger,
        "source": source,
        "document_kind": "editor_projection",
        "document": document,
        "artifact": artifact,
        "validation": validation_value,
        "updated_at_unix_ms": updated_at_unix_ms,
        "registry_source": "meta/mobpacks/create",
        "template": template_id,
        "revision": revision,
        "draft_revision": revision,
        "etag": draft_etag,
        "draft_etag": draft_etag
    });
    rows.insert(id.clone(), row.clone());
    admit_draft_store_write(&mut rows, &id, before)?;
    let durability_warning = write_mobpack_draft_store(&path, &rows)?;
    drop(lock);
    // The create response keeps the freshly cloned editor document (no
    // artifact re-import); only the store-internal history fields are
    // projected to can_undo/can_redo.
    let row = draft_row_without_history(&row);
    Ok(draft_store_write_reply(
        json!({
            "source": "meta/mobpacks/create",
            "row": row,
            "rows": draft_summaries(&rows),
        }),
        &path,
        durability_warning,
    ))
}

/// The most characters of a draft's name, description and other labels
/// that its summary carries.
const MOBPACK_DRAFT_SUMMARY_MAX_CHARS: usize = 256;

/// Every stored draft as a summary ([`draft_summary`]).
fn draft_summaries(rows: &BTreeMap<String, Value>) -> Vec<Value> {
    rows.values().map(draft_summary).collect()
}

/// A draft as replies list it: its id, revision and etag and what the
/// library shows of it, without its document, archive, validation or
/// history, so no reply grows with the drafts' documents. `get` returns a
/// draft's document, and so does the reply of the write that changed it.
fn draft_summary(row: &Value) -> Value {
    let mut summary = serde_json::Map::new();
    for key in [
        "id",
        "revision",
        "draft_revision",
        "etag",
        "draft_etag",
        "updated_at_unix_ms",
        "runtime_projection",
    ] {
        if let Some(value) = row.get(key) {
            summary.insert(key.to_string(), value.clone());
        }
    }
    for key in [
        "name",
        "version",
        "stage",
        "trigger",
        "source",
        "registry_source",
        "document_kind",
    ] {
        if let Some(text) = row.get(key).and_then(Value::as_str) {
            summary.insert(key.to_string(), json!(draft_summary_text(text)));
        }
    }
    if let Some(description) = draft_description(row) {
        summary.insert(
            "description".to_string(),
            json!(draft_summary_text(description)),
        );
    }
    let can_step = |key: &str, flag: &str| {
        row.get(key)
            .and_then(Value::as_array)
            .is_some_and(|entries| !entries.is_empty())
            || row.get(flag).and_then(Value::as_bool).unwrap_or(false)
    };
    summary.insert(
        "can_undo".to_string(),
        json!(can_step("history", "can_undo")),
    );
    summary.insert(
        "can_redo".to_string(),
        json!(can_step("future", "can_redo")),
    );
    let stored = row.get("document").map_or(0, value_skill_content_bytes);
    if stored > MOBPACK_DOCUMENT_MAX_SKILL_CONTENT_BYTES {
        summary.insert("document_authority".to_string(), json!("refused"));
        summary.insert(
            "document_refusal".to_string(),
            json!(document_skill_content_too_large(stored)),
        );
    }
    Value::Object(summary)
}

/// At most [`MOBPACK_DRAFT_SUMMARY_MAX_CHARS`] characters of a summary label.
fn draft_summary_text(text: &str) -> String {
    text.chars().take(MOBPACK_DRAFT_SUMMARY_MAX_CHARS).collect()
}

/// What the library shows as a draft's description: its flow's description,
/// or else the task of its flow's input step.
fn draft_description(row: &Value) -> Option<&str> {
    fn nonempty(text: Option<&Value>) -> Option<&str> {
        text.and_then(Value::as_str)
            .map(str::trim)
            .filter(|text| !text.is_empty())
    }
    let flow = row.get("document")?.get("flow")?;
    nonempty(flow.get("description")).or_else(|| {
        let input = flow
            .get("steps")?
            .as_array()?
            .iter()
            .find(|step| step.get("type").and_then(Value::as_str) == Some("input"))?;
        nonempty(input.get("task"))
    })
}

/// The draft a write's reply carries: without its undo and redo snapshots,
/// or, for a document past the skill content cap (a store written before
/// the cap, or by hand), a placeholder that says why.
fn stored_draft_row(row: &Value) -> Value {
    let stored = row.get("document").map_or(0, value_skill_content_bytes);
    if stored > MOBPACK_DOCUMENT_MAX_SKILL_CONTENT_BYTES {
        return refused_draft_row(row, &document_skill_content_too_large(stored));
    }
    draft_row_without_history(row)
}

/// History snapshots stay in the store; an outgoing row only advertises
/// whether Meta can step. The row is copied without its snapshots, which are
/// most of a store's bytes.
fn draft_row_without_history(row: &Value) -> Value {
    let Some(object) = row.as_object() else {
        return row.clone();
    };
    let can_step = |key: &str| {
        object
            .get(key)
            .and_then(Value::as_array)
            .is_some_and(|entries| !entries.is_empty())
    };
    let mut stripped = object
        .iter()
        .filter(|(key, _)| !matches!(key.as_str(), "history" | "future"))
        .map(|(key, value)| (key.clone(), value.clone()))
        .collect::<serde_json::Map<_, _>>();
    stripped.insert("can_undo".to_string(), json!(can_step("history")));
    stripped.insert("can_redo".to_string(), json!(can_step("future")));
    Value::Object(stripped)
}

/// The draft `get` returns: the stored draft ([`stored_draft_row`]) with its
/// document re-imported from the draft's archive once it validated, so the
/// archive is the draft's authority. Only `get` re-imports, one draft per
/// call and outside the draft store lock; every other reply carries its
/// drafts as stored.
fn normalize_mobpack_draft_row(row: &Value) -> Value {
    let mut row = stored_draft_row(row);
    let Some(artifact) = row.get("artifact") else {
        return row;
    };
    if artifact.get("kind").and_then(Value::as_str) != Some("mobpack_archive") {
        return row;
    }
    let Some(content_base64) = artifact
        .get("content_base64")
        .and_then(Value::as_str)
        .map(str::trim)
        .filter(|value| !value.is_empty())
    else {
        return row;
    };
    let import = import_mobpack(&json!({
        "content_base64": content_base64,
        "filename": artifact.get("filename").and_then(Value::as_str),
        "source_media_type": artifact
            .get("media_type")
            .and_then(Value::as_str)
            .unwrap_or(MOBPACK_MEDIA_TYPE),
    }));
    match import {
        Ok(imported) => {
            row["document_kind"] = json!("editor_projection");
            row["document_source"] = json!("mobpack_archive");
            row["document_authority"] = json!("artifact");
            row["document"] = imported["document"].clone();
            row["validation"] = imported["validation"].clone();
        }
        Err(error) => {
            row["document_source"] = json!("editor_projection");
            row["document_authority"] = json!("fallback");
            row["artifact_import_error"] = json!(error);
        }
    }
    row
}

/// A draft row whose document is not returned, with why. It keeps the row's
/// identity and revision so the editor can list it and delete it.
fn refused_draft_row(row: &Value, reason: &str) -> Value {
    let mut placeholder = [
        "id",
        "name",
        "version",
        "stage",
        "trigger",
        "source",
        "updated_at_unix_ms",
        "registry_source",
        "revision",
        "draft_revision",
        "etag",
        "draft_etag",
    ]
    .into_iter()
    .filter_map(|key| row.get(key).map(|value| (key.to_string(), value.clone())))
    .collect::<serde_json::Map<_, _>>();
    placeholder.insert("document".to_string(), Value::Null);
    placeholder.insert("document_authority".to_string(), json!("refused"));
    placeholder.insert("document_refusal".to_string(), json!(reason));
    placeholder.insert("can_undo".to_string(), json!(false));
    placeholder.insert("can_redo".to_string(), json!(false));
    Value::Object(placeholder)
}

pub fn list_mobpack_drafts(params: &Value) -> Result<Value, String> {
    list_mobpack_drafts_with_runtime(params, None)
}

pub fn list_mobpack_drafts_with_runtime(
    params: &Value,
    runtime: Option<&MobpackRuntimeCatalogState>,
) -> Result<Value, String> {
    list_drafts(params, runtime).map_err(|failure| failure.message)
}

fn list_drafts(
    params: &Value,
    runtime: Option<&MobpackRuntimeCatalogState>,
) -> Result<Value, DraftStoreFailure> {
    let path = mobpack_draft_store_path(params)?;
    let lock = lock_draft_store()?;
    let (rows, _) = read_draft_store(&path)?;
    drop(lock);
    let runtime_rows = runtime
        .map(|state| {
            state
                .runtime_flow_rows
                .iter()
                .map(draft_summary)
                .collect::<Vec<_>>()
        })
        .unwrap_or_default();
    let runtime_ids = runtime_rows
        .iter()
        .filter_map(|row| row.get("id").and_then(Value::as_str).map(str::to_string))
        .collect::<BTreeSet<_>>();
    let draft_rows = draft_summaries(&rows).into_iter().filter(|row| {
        row.get("id")
            .and_then(Value::as_str)
            .map(|id| !runtime_ids.contains(id))
            .unwrap_or(true)
    });
    let merged_rows = runtime_rows
        .into_iter()
        .chain(draft_rows)
        .collect::<Vec<_>>();
    Ok(draft_store_reply(
        json!({
            "source": "meta/mobpacks/list",
            "runtime_backed": runtime.is_some(),
            "rows": merged_rows,
        }),
        &path,
    ))
}

pub fn get_mobpack_draft(params: &Value) -> Result<Value, String> {
    get_mobpack_draft_with_runtime(params, None)
}

pub fn get_mobpack_draft_with_runtime(
    params: &Value,
    runtime: Option<&MobpackRuntimeCatalogState>,
) -> Result<Value, String> {
    get_draft(params, runtime).map_err(|failure| failure.message)
}

fn get_draft(
    params: &Value,
    runtime: Option<&MobpackRuntimeCatalogState>,
) -> Result<Value, DraftStoreFailure> {
    let id = params
        .get("id")
        .and_then(Value::as_str)
        .map(str::trim)
        .filter(|value| !value.is_empty())
        .ok_or_else(|| "meta/mobpacks/get requires id".to_string())?;
    if let Some(row) = runtime
        .into_iter()
        .flat_map(|state| state.runtime_flow_rows.iter())
        .find(|row| row.get("id").and_then(Value::as_str) == Some(id))
    {
        return Ok(json!({
            "source": "meta/mobpacks/get",
            "runtime_backed": true,
            "row": row,
        }));
    }
    let path = mobpack_draft_store_path(params)?;
    let lock = lock_draft_store()?;
    let (rows, _) = read_draft_store(&path)?;
    drop(lock);
    let row = rows
        .get(id)
        .ok_or_else(|| format!("mobpack draft not found: {id}"))?;
    let row = normalize_mobpack_draft_row(row);
    Ok(draft_store_reply(
        json!({
            "source": "meta/mobpacks/get",
            "runtime_backed": runtime.is_some(),
            "row": row,
        }),
        &path,
    ))
}

pub fn save_mobpack_draft(params: &Value) -> Result<Value, String> {
    save_draft(params).map_err(|failure| failure.message)
}

fn save_draft(params: &Value) -> Result<Value, DraftStoreFailure> {
    let path = mobpack_draft_store_path(params)?;
    // The row is built (validated and exported) before the store is locked:
    // the lock covers only the store's read, checks and write.
    let mut row = mobpack_draft_row_from_params(params, 0)?;
    let id = row["id"]
        .as_str()
        .ok_or_else(|| "mobpack draft row missing id".to_string())?
        .to_string();
    let lock = lock_draft_store()?;
    let (mut rows, before) = read_draft_store(&path)?;
    if !rows.contains_key(&id) && rows.len() >= MOBPACK_DRAFT_STORE_MAX_DRAFTS {
        return Err(DraftStoreRefusal::TooManyDrafts.into());
    }
    let existing = rows.get(&id);
    let current_revision = mobpack_draft_revision_from_row(existing);
    if let Some(expected_revision) = mobpack_draft_expected_revision(params)
        && expected_revision != current_revision
    {
        return Err(format!(
            "mobpack draft revision conflict for {id}: expected {expected_revision}, found {current_revision}"
        ).into());
    }
    if let Some(expected_etag) = mobpack_draft_expected_etag(params) {
        let current_etag = mobpack_draft_etag(&id, current_revision);
        if expected_etag != current_etag {
            return Err(format!(
                "mobpack draft etag conflict for {id}: expected {expected_etag}, found {current_etag}"
            ).into());
        }
    }
    set_draft_row_revision(&mut row, &id, current_revision.saturating_add(1));
    attach_draft_history_on_save(existing, &mut row);
    rows.insert(id.clone(), row);
    admit_draft_store_write(&mut rows, &id, before)?;
    let durability_warning = write_mobpack_draft_store(&path, &rows)?;
    drop(lock);
    let row = rows.get(&id).map(stored_draft_row).unwrap_or_default();
    Ok(draft_store_write_reply(
        json!({
            "source": "meta/mobpacks/save",
            "row": row,
            "rows": draft_summaries(&rows),
        }),
        &path,
        durability_warning,
    ))
}

/// Maximum number of undo steps retained per draft in the store.
const MOBPACK_DRAFT_HISTORY_LIMIT: usize = 25;

/// Carry the Meta-owned operation history across a save: the previous
/// document becomes an undo step (bounded), and a changed authoring head
/// invalidates any redo entries. Saves with an unchanged document keep both
/// stacks as they are, so undo/redo themselves persist through the autosave
/// that follows them.
fn attach_draft_history_on_save(existing: Option<&Value>, row: &mut Value) {
    let Some(existing) = existing else {
        return;
    };
    let mut history = existing
        .get("history")
        .and_then(Value::as_array)
        .cloned()
        .unwrap_or_default();
    let previous_document = existing.get("document");
    let document_changed = previous_document.is_some() && previous_document != row.get("document");
    if !document_changed {
        row["history"] = Value::Array(history);
        if let Some(future) = existing.get("future") {
            row["future"] = future.clone();
        }
        return;
    }
    if let Some(previous) = previous_document {
        history.push(previous.clone());
        if history.len() > MOBPACK_DRAFT_HISTORY_LIMIT {
            let excess = history.len() - MOBPACK_DRAFT_HISTORY_LIMIT;
            history.drain(0..excess);
        }
    }
    row["history"] = Value::Array(history);
}

enum MobpackDraftHistoryStep {
    Undo,
    Redo,
}

pub fn undo_mobpack_draft(params: &Value) -> Result<Value, String> {
    step_mobpack_draft_history(params, MobpackDraftHistoryStep::Undo)
        .map_err(|failure| failure.message)
}

pub fn redo_mobpack_draft(params: &Value) -> Result<Value, String> {
    step_mobpack_draft_history(params, MobpackDraftHistoryStep::Redo)
        .map_err(|failure| failure.message)
}

#[cfg(test)]
std::thread_local! {
    /// Runs once on this thread between an undo's or a redo's read of the
    /// draft store and its write, for the tests of a draft that changes in
    /// between.
    static DRAFT_STEP_BETWEEN_READ_AND_WRITE: std::cell::RefCell<Option<Box<dyn FnOnce()>>> =
        const { std::cell::RefCell::new(None) };
}

/// Run the hook set on this thread, if any, between an undo's or a redo's
/// read of the draft store and its write.
#[cfg(test)]
fn run_draft_step_between_read_and_write() {
    if let Some(between) = DRAFT_STEP_BETWEEN_READ_AND_WRITE.with(|hook| hook.borrow_mut().take()) {
        between();
    }
}

/// Meta-owned undo/redo over the draft store. The history lives with the
/// draft (bounded document snapshots the store itself recorded on save), so
/// the browser never authors restore states; stepping rebuilds the row
/// through the same canonicalization and validation as a save and bumps the
/// draft revision.
fn step_mobpack_draft_history(
    params: &Value,
    step: MobpackDraftHistoryStep,
) -> Result<Value, DraftStoreFailure> {
    let (source, head) = match step {
        MobpackDraftHistoryStep::Undo => ("meta/mobpacks/undo", "undo"),
        MobpackDraftHistoryStep::Redo => ("meta/mobpacks/redo", "redo"),
    };
    let id = params
        .get("id")
        .and_then(Value::as_str)
        .map(str::trim)
        .filter(|value| !value.is_empty())
        .ok_or_else(|| format!("{source} requires id"))?
        .to_string();
    let path = mobpack_draft_store_path(params)?;
    // The draft is read under the lock and its restored row built without
    // it; the write below checks the draft is still the one read.
    let lock = lock_draft_store()?;
    let (rows, _) = read_draft_store(&path)?;
    drop(lock);
    let existing = rows
        .get(&id)
        .cloned()
        .ok_or_else(|| format!("mobpack draft not found: {id}"))?;
    let current_revision = mobpack_draft_revision_from_row(Some(&existing));
    if let Some(expected_revision) = mobpack_draft_expected_revision(params)
        && expected_revision != current_revision
    {
        return Err(format!(
            "{source} draft revision conflict for {id}: expected {expected_revision}, found {current_revision}"
        ).into());
    }
    if let Some(expected_etag) = mobpack_draft_expected_etag(params) {
        let current_etag = mobpack_draft_etag(&id, current_revision);
        if expected_etag != current_etag {
            return Err(format!(
                "{source} draft etag conflict for {id}: expected {expected_etag}, found {current_etag}"
            ).into());
        }
    }
    let mut history = existing
        .get("history")
        .and_then(Value::as_array)
        .cloned()
        .unwrap_or_default();
    let mut future = existing
        .get("future")
        .and_then(Value::as_array)
        .cloned()
        .unwrap_or_default();
    let current_document = existing.get("document").cloned().unwrap_or(Value::Null);
    let restored = match step {
        MobpackDraftHistoryStep::Undo => {
            let Some(document) = history.pop() else {
                return Ok(draft_store_reply(
                    json!({
                        "source": source,
                        "stepped": false,
                        "reason": format!("nothing to {head}"),
                        "row": stored_draft_row(&existing),
                        "rows": draft_summaries(&rows),
                    }),
                    &path,
                ));
            };
            future.push(current_document);
            document
        }
        MobpackDraftHistoryStep::Redo => {
            let Some(document) = future.pop() else {
                return Ok(draft_store_reply(
                    json!({
                        "source": source,
                        "stepped": false,
                        "reason": format!("nothing to {head}"),
                        "row": stored_draft_row(&existing),
                        "rows": draft_summaries(&rows),
                    }),
                    &path,
                ));
            };
            history.push(current_document);
            document
        }
    };
    if future.len() > MOBPACK_DRAFT_HISTORY_LIMIT {
        let excess = future.len() - MOBPACK_DRAFT_HISTORY_LIMIT;
        future.drain(0..excess);
    }
    let mut row = mobpack_draft_row_from_params(
        &json!({
            "id": id,
            "document": restored,
            "trigger": existing.get("trigger").and_then(Value::as_str),
            "source": source,
        }),
        current_revision.saturating_add(1),
    )?;
    row["history"] = Value::Array(history);
    row["future"] = Value::Array(future);
    #[cfg(test)]
    run_draft_step_between_read_and_write();
    let lock = lock_draft_store()?;
    let (mut rows, before) = read_draft_store(&path)?;
    let stored_revision = rows
        .get(&id)
        .map_or(0, |stored| mobpack_draft_revision_from_row(Some(stored)));
    if !rows.contains_key(&id) || stored_revision != current_revision {
        return Err(format!(
            "{source} draft revision conflict for {id}: expected {current_revision}, found {stored_revision}"
        )
        .into());
    }
    // The same revision need not be the same draft: one deleted, created
    // again and saved back to it has it too. Only the draft as read is
    // overwritten; any other is a revision conflict, which the editor
    // retries like any other.
    if rows.get(&id) != Some(&existing) {
        return Err(format!(
            "{source} draft revision conflict for {id}: the draft at revision {current_revision} changed after it was read"
        )
        .into());
    }
    rows.insert(id.clone(), row);
    admit_draft_store_write(&mut rows, &id, before)?;
    let durability_warning = write_mobpack_draft_store(&path, &rows)?;
    drop(lock);
    let row = rows.get(&id).map(stored_draft_row).unwrap_or_default();
    Ok(draft_store_write_reply(
        json!({
            "source": source,
            "stepped": true,
            "row": row,
            "rows": draft_summaries(&rows),
        }),
        &path,
        durability_warning,
    ))
}

pub fn delete_mobpack_draft(params: &Value) -> Result<Value, String> {
    delete_draft(params).map_err(|failure| failure.message)
}

fn delete_draft(params: &Value) -> Result<Value, DraftStoreFailure> {
    let id = params
        .get("id")
        .and_then(Value::as_str)
        .map(str::trim)
        .filter(|value| !value.is_empty())
        .ok_or_else(|| "meta/mobpacks/delete requires id".to_string())?
        .to_string();
    let path = mobpack_draft_store_path(params)?;
    let lock = lock_draft_store()?;
    let (mut rows, _) = read_draft_store(&path)?;
    let current_revision = mobpack_draft_revision_from_row(rows.get(&id));
    if let Some(expected_revision) = mobpack_draft_expected_revision(params)
        && expected_revision != current_revision
    {
        return Err(format!(
            "meta/mobpacks/delete draft revision conflict for {id}: expected {expected_revision}, found {current_revision}"
        ).into());
    }
    if let Some(expected_etag) = mobpack_draft_expected_etag(params) {
        let current_etag = mobpack_draft_etag(&id, current_revision);
        if expected_etag != current_etag {
            return Err(format!(
                "meta/mobpacks/delete draft etag conflict for {id}: expected {expected_etag}, found {current_etag}"
            ).into());
        }
    }
    let deleted = rows.remove(&id).is_some();
    let durability_warning = write_mobpack_draft_store(&path, &rows)?;
    drop(lock);
    Ok(draft_store_write_reply(
        json!({
            "source": "meta/mobpacks/delete",
            "id": id,
            "deleted": deleted,
            "rows": draft_summaries(&rows),
        }),
        &path,
        durability_warning,
    ))
}

pub fn apply_mobpack_authoring_operation(params: &Value) -> Result<Value, String> {
    apply_mobpack_authoring_operation_with_runtime(params, None)
}

pub fn apply_mobpack_authoring_operation_with_runtime(
    params: &Value,
    runtime: Option<&MobpackRuntimeCatalogState>,
) -> Result<Value, String> {
    enforce_mobpack_draft_expected_revision(params, "meta/mobpacks/apply_operation")?;
    let mut document = document_from_params(params)?;
    let operation = params
        .get("operation")
        .and_then(Value::as_object)
        .ok_or_else(|| "meta/mobpacks/apply_operation requires operation object".to_string())?;
    let operation_type = operation
        .get("type")
        .or_else(|| operation.get("kind"))
        .and_then(Value::as_str)
        .map(str::trim)
        .filter(|value| !value.is_empty())
        .ok_or_else(|| "meta/mobpacks/apply_operation requires operation.type".to_string())?;
    // No operation but a delete reads a graph past the structure caps, so a
    // document past them can be brought back under them; every operation is
    // checked again after its edit.
    let graph_before = graph_structure_sizes(&document);
    if !operation_only_removes(operation_type) {
        refuse_graph_past_structure_caps(&document)?;
    }
    if operation.get("document").is_some() {
        return Err(format!(
            "{operation_type} does not accept operation.document; use meta/mobpacks/import or create/save for document replacement"
        ));
    }
    enforce_expected_catalog_snapshot(params, operation, operation_type, runtime)?;
    let selection = match operation_type {
        "sync_graph_to_flow" => apply_sync_graph_to_flow_operation(&mut document, operation)?,
        "reconcile_members" => apply_reconcile_members_operation(&mut document, operation)?,
        "reconcile_condition_fields" => {
            apply_reconcile_condition_fields_operation(&mut document, operation)?
        }
        "reconcile_contract_refs" => {
            apply_reconcile_contract_refs_operation(&mut document, operation)?
        }
        "add_agent_definition" => {
            apply_add_agent_definition_operation(&mut document, operation, runtime)?
        }
        "update_member" => apply_update_member_operation(&mut document, operation)?,
        "add_member_tool" => apply_member_tool_operation(&mut document, operation, true, runtime)?,
        "remove_member_tool" => {
            apply_member_tool_operation(&mut document, operation, false, runtime)?
        }
        "toggle_member_skill" => {
            apply_member_skill_operation(&mut document, operation, SkillOperation::Toggle, runtime)?
        }
        "remove_member_skill" => {
            apply_member_skill_operation(&mut document, operation, SkillOperation::Remove, runtime)?
        }
        "create_inline_skill" => apply_create_inline_skill_operation(&mut document, operation)?,
        "delete_member" => apply_delete_member_operation(&mut document, operation)?,
        "assign_member_schema" => apply_assign_member_schema_operation(&mut document, operation)?,
        "add_schema" => apply_add_schema_operation(&mut document, operation)?,
        "update_schema" => apply_update_schema_operation(&mut document, operation)?,
        "rename_schema" => apply_rename_schema_operation(&mut document, operation)?,
        "delete_schema" => apply_delete_schema_operation(&mut document, operation)?,
        "add_schema_field" => apply_add_schema_field_operation(&mut document, operation)?,
        "update_schema_field" => apply_update_schema_field_operation(&mut document, operation)?,
        "rename_schema_field" => apply_rename_schema_field_operation(&mut document, operation)?,
        "delete_schema_field" => apply_delete_schema_field_operation(&mut document, operation)?,
        "update_deploy_settings" => {
            apply_update_deploy_settings_operation(&mut document, operation)?
        }
        "update_mob_settings" => apply_update_mob_settings_operation(&mut document, operation)?,
        "update_role_wiring" => apply_update_role_wiring_operation(&mut document, operation)?,
        "add_input_param" => apply_add_input_param_operation(&mut document, operation)?,
        "update_input_param" => apply_update_input_param_operation(&mut document, operation)?,
        "rename_input_param" => apply_rename_input_param_operation(&mut document, operation)?,
        "delete_input_param" => apply_delete_input_param_operation(&mut document, operation)?,
        "insert_flow_step" => apply_insert_flow_step_operation(&mut document, operation)?,
        "update_flow_step" => apply_update_flow_step_operation(&mut document, operation)?,
        "apply_flow_step_edit" => apply_flow_step_edit_operation(&mut document, operation)?,
        "delete_flow_step" => apply_delete_flow_step_operation(&mut document, operation)?,
        "insert_graph_node" => apply_insert_graph_node_operation(&mut document, operation)?,
        "apply_graph_node_edit" => apply_graph_node_edit_operation(&mut document, operation)?,
        "move_graph_node" => apply_move_graph_node_operation(&mut document, operation)?,
        "delete_graph_node" => apply_delete_graph_node_operation(&mut document, operation)?,
        "connect_graph_nodes" => apply_connect_graph_nodes_operation(&mut document, operation)?,
        "apply_graph_edge_edit" => apply_graph_edge_edit_operation(&mut document, operation)?,
        "delete_graph_edge" => apply_delete_graph_edge_operation(&mut document, operation)?,
        other => {
            return Err(format!(
                "meta/mobpacks/apply_operation unsupported operation.type: {other}"
            ));
        }
    };
    refuse_graph_grown_past_structure_caps(&document, graph_before)?;
    // An authoring edit never runs `rkat` or writes an archive, whatever its
    // params ask: `meta/mobpacks/validate` is the one method with an `rkat`
    // phase, and the one the host-mutation advertisement names for it.
    let validation = validate_document(&document);
    Ok(json!({
        "source": "meta/mobpacks/apply_operation",
        "operation": operation_type,
        "ok": validation.ok,
        "document": document,
        "selection": selection,
        "validation": validation,
    }))
}

fn enforce_expected_catalog_snapshot(
    params: &Value,
    operation: &serde_json::Map<String, Value>,
    operation_type: &str,
    runtime: Option<&MobpackRuntimeCatalogState>,
) -> Result<(), String> {
    if !operation_uses_authoring_catalog(operation_type) {
        return Ok(());
    }
    let Some(expected) = expected_catalog_snapshot_id(params, operation) else {
        return Ok(());
    };
    let current = current_authoring_catalog_snapshot_id(runtime)
        .ok_or_else(|| "Meta authoring catalog did not expose catalog_snapshot.id".to_string())?;
    if expected == current {
        return Ok(());
    }
    Err(format!(
        "meta/mobpacks/apply_operation catalog snapshot conflict for {operation_type}: expected {expected}, found {current}"
    ))
}

fn operation_uses_authoring_catalog(operation_type: &str) -> bool {
    matches!(
        operation_type,
        "add_agent_definition" | "add_member_tool" | "toggle_member_skill"
    )
}

fn expected_catalog_snapshot_id(
    params: &Value,
    operation: &serde_json::Map<String, Value>,
) -> Option<String> {
    value_catalog_snapshot_id(params)
        .or_else(|| value_catalog_snapshot_id(&Value::Object(operation.clone())))
}

fn value_catalog_snapshot_id(value: &Value) -> Option<String> {
    value
        .get("expected_catalog_snapshot_id")
        .or_else(|| value.get("expectedCatalogSnapshotId"))
        .or_else(|| value.get("catalog_snapshot_id"))
        .or_else(|| value.get("catalogSnapshotId"))
        .and_then(Value::as_str)
        .or_else(|| {
            value
                .get("catalog_snapshot")
                .or_else(|| value.get("catalogSnapshot"))
                .and_then(|snapshot| {
                    snapshot
                        .get("id")
                        .and_then(Value::as_str)
                        .or_else(|| snapshot.as_str())
                })
        })
        .map(str::trim)
        .filter(|snapshot| !snapshot.is_empty())
        .map(ToString::to_string)
}

fn current_authoring_catalog_snapshot_id(
    runtime: Option<&MobpackRuntimeCatalogState>,
) -> Option<String> {
    mobpack_catalogs_response_with_runtime(runtime)["catalog_snapshot"]["id"]
        .as_str()
        .map(ToString::to_string)
}

fn value_kind(value: &Value) -> &'static str {
    match value {
        Value::Null => "null",
        Value::Bool(_) => "bool",
        Value::Number(_) => "number",
        Value::String(_) => "string",
        Value::Array(_) => "array",
        Value::Object(_) => "object",
    }
}

fn operation_selection_or_clear(operation: &serde_json::Map<String, Value>) -> Value {
    operation
        .get("selection")
        .cloned()
        .unwrap_or_else(|| json!({ "kind": null, "id": null }))
}

fn apply_sync_graph_to_flow_operation(
    document: &mut MobpackDocument,
    operation: &serde_json::Map<String, Value>,
) -> Result<Value, String> {
    // The advanced-mode canvas keeps the user's node/edge authoring as-is;
    // the flow is derived from it. Validation accepts the gate-less graph
    // because `validate_graph_projection` proves the equivalence by
    // re-deriving the flow from the graph.
    document.flow = graph_to_flow_within_caps(document)?;
    reconcile_flow_step_launch_modes(document);
    Ok(operation_selection_or_clear(operation))
}

fn apply_reconcile_members_operation(
    document: &mut MobpackDocument,
    operation: &serde_json::Map<String, Value>,
) -> Result<Value, String> {
    reconcile_document_after_member_change(document);
    prune_mob_settings_for_current_members(document);
    Ok(operation_selection_or_clear(operation))
}

fn apply_reconcile_condition_fields_operation(
    document: &mut MobpackDocument,
    operation: &serde_json::Map<String, Value>,
) -> Result<Value, String> {
    reconcile_condition_field_availability(document);
    Ok(operation_selection_or_clear(operation))
}

fn apply_reconcile_contract_refs_operation(
    document: &mut MobpackDocument,
    operation: &serde_json::Map<String, Value>,
) -> Result<Value, String> {
    prune_member_refs_for_contract(document);
    reconcile_document_after_member_change(document);
    prune_mob_settings_for_current_members(document);
    reconcile_condition_field_availability(document);
    if !document.deploy.is_object() {
        document.deploy = json!({});
    }
    document.deploy["command"] = json!("rkat mob run");
    Ok(operation_selection_or_clear(operation))
}

fn apply_delete_member_operation(
    document: &mut MobpackDocument,
    operation: &serde_json::Map<String, Value>,
) -> Result<Value, String> {
    let member_id = operation_member_id(operation)?;
    let mut members = document
        .members
        .as_array()
        .cloned()
        .unwrap_or_else(Vec::new);
    let index = member_index_by_id(&members, &member_id)
        .ok_or_else(|| format!("member not found: {member_id}"))?;
    let removed = members.remove(index);
    let removed_names = member_identity_values(&removed);
    document.members = Value::Array(members);
    prune_mob_settings_for_removed_member(&mut document.mob_settings, &removed_names);
    reconcile_document_after_member_change(document);
    Ok(json!({ "kind": null, "id": null }))
}

fn apply_assign_member_schema_operation(
    document: &mut MobpackDocument,
    operation: &serde_json::Map<String, Value>,
) -> Result<Value, String> {
    let member_id = operation_member_id(operation)?;
    let schema_id = operation
        .get("schema_id")
        .or_else(|| operation.get("schemaId"))
        .or_else(|| operation.get("schema"))
        .and_then(Value::as_str)
        .map(str::trim)
        .unwrap_or_default()
        .to_string();
    if !schema_id.is_empty() && schema_index_by_id(&document.schemas, &schema_id).is_none() {
        return Err(format!("schema not found: {schema_id}"));
    }
    let mut members = document
        .members
        .as_array()
        .cloned()
        .unwrap_or_else(Vec::new);
    let index = member_index_by_id(&members, &member_id)
        .ok_or_else(|| format!("member not found: {member_id}"))?;
    let old_schema = members[index]
        .get("schema")
        .and_then(Value::as_str)
        .unwrap_or_default()
        .to_string();
    if old_schema != schema_id {
        for field_name in schema_field_names(&document.schemas, &old_schema) {
            rewrite_schema_field_references(document, &old_schema, &field_name, "");
        }
    }
    members[index]["schema"] = Value::String(schema_id);
    document.members = Value::Array(members);
    Ok(json!({ "kind": "agent", "id": member_id }))
}

fn next_schema_id(schemas: &[Value], prefix: &str) -> String {
    let prefix = input_param_name(prefix, "Artifact");
    let used = schemas
        .iter()
        .filter_map(|schema| schema.get("id").and_then(Value::as_str))
        .map(str::trim)
        .filter(|id| !id.is_empty())
        .collect::<BTreeSet<_>>();
    let mut index = 1;
    loop {
        let id = format!("{prefix}{index}");
        if !used.contains(id.as_str()) {
            return id;
        }
        index += 1;
    }
}

fn next_schema_field_id(fields: &[Value]) -> String {
    let used = fields
        .iter()
        .filter_map(|field| field.get("id").and_then(Value::as_str))
        .map(str::trim)
        .filter(|id| !id.is_empty())
        .collect::<BTreeSet<_>>();
    let mut index = 1;
    loop {
        let id = format!("f{index}");
        if !used.contains(id.as_str()) {
            return id;
        }
        index += 1;
    }
}

fn unique_schema_draft_field_name(fields: &[Value], raw: &str) -> String {
    let base = input_param_name(raw, "field");
    let taken = fields
        .iter()
        .filter_map(|field| field.get("name").and_then(Value::as_str))
        .map(str::trim)
        .filter(|name| !name.is_empty())
        .collect::<BTreeSet<_>>();
    if !taken.contains(base.as_str()) {
        return base;
    }
    let mut index = 2;
    loop {
        let candidate = format!("{base}_{index}");
        if !taken.contains(candidate.as_str()) {
            return candidate;
        }
        index += 1;
    }
}

fn schema_draft_contract() -> Result<(Value, String), String> {
    let schema = mobpack_schema_response();
    let mob_definition = schema
        .get("mob_definition")
        .and_then(Value::as_object)
        .ok_or_else(|| "Meta schema is missing mob_definition".to_string())?;
    let field_type = mob_definition
        .get("defaults")
        .and_then(Value::as_object)
        .and_then(|defaults| defaults.get("schema_field_type"))
        .and_then(Value::as_str)
        .map(str::trim)
        .filter(|value| !value.is_empty())
        .unwrap_or("string");
    if !is_editor_schema_field_type(field_type) {
        return Err(format!(
            "Meta schema default schema_field_type is unsupported: {field_type}"
        ));
    }
    let draft = mob_definition
        .get("editor_schema_draft")
        .cloned()
        .filter(Value::is_object)
        .ok_or_else(|| "Meta schema is missing mob_definition.editor_schema_draft".to_string())?;
    Ok((draft, field_type.to_string()))
}

fn schema_field_from_draft(fields: &[Value], field_key: &str) -> Result<Value, String> {
    let (draft, field_type) = schema_draft_contract()?;
    let field = draft
        .get(field_key)
        .and_then(Value::as_object)
        .ok_or_else(|| format!("Meta schema is missing editor_schema_draft.{field_key}"))?;
    let name = field
        .get("name")
        .and_then(Value::as_str)
        .map(str::trim)
        .filter(|value| !value.is_empty())
        .unwrap_or("field");
    let enum_values = field
        .get("enumValues")
        .and_then(Value::as_array)
        .cloned()
        .unwrap_or_default();
    Ok(json!({
        "id": next_schema_field_id(fields),
        "name": unique_schema_draft_field_name(fields, name),
        "type": field_type,
        "required": field.get("required").and_then(Value::as_bool).unwrap_or(true),
        "description": field.get("description").and_then(Value::as_str).unwrap_or(""),
        "enumValues": enum_values,
    }))
}

fn schema_from_draft(schemas: &[Value]) -> Result<Value, String> {
    let (draft, _) = schema_draft_contract()?;
    let prefix = draft
        .get("schema_id_prefix")
        .and_then(Value::as_str)
        .map(str::trim)
        .filter(|value| !value.is_empty())
        .unwrap_or("Artifact");
    Ok(json!({
        "id": next_schema_id(schemas, prefix),
        "description": "",
        "fields": [schema_field_from_draft(&[], "initial_field")?],
    }))
}

fn apply_add_schema_operation(
    document: &mut MobpackDocument,
    operation: &serde_json::Map<String, Value>,
) -> Result<Value, String> {
    let mut schemas = document
        .schemas
        .as_array()
        .cloned()
        .unwrap_or_else(Vec::new);
    let schema = operation
        .get("schema")
        .cloned()
        .map(Ok)
        .unwrap_or_else(|| schema_from_draft(&schemas))?;
    let schema_id = schema
        .get("id")
        .and_then(Value::as_str)
        .map(str::trim)
        .filter(|value| !value.is_empty())
        .ok_or_else(|| "add_schema requires schema.id".to_string())?
        .to_string();
    if schemas.iter().any(|schema| {
        schema
            .get("id")
            .and_then(Value::as_str)
            .is_some_and(|id| id == schema_id)
    }) {
        return Err(format!("schema already exists: {schema_id}"));
    }
    schemas.push(schema);
    document.schemas = Value::Array(schemas);
    Ok(json!({ "kind": "schema", "id": schema_id }))
}

fn apply_update_schema_operation(
    document: &mut MobpackDocument,
    operation: &serde_json::Map<String, Value>,
) -> Result<Value, String> {
    let schema_id = operation_schema_id(operation)?;
    let patch = operation
        .get("patch")
        .and_then(Value::as_object)
        .ok_or_else(|| "update_schema requires patch object".to_string())?;
    let mut schemas = document
        .schemas
        .as_array()
        .cloned()
        .unwrap_or_else(Vec::new);
    let index = schema_index_in_slice(&schemas, &schema_id)
        .ok_or_else(|| format!("schema not found: {schema_id}"))?;
    let schema = schemas[index]
        .as_object_mut()
        .ok_or_else(|| format!("schema is not an object: {schema_id}"))?;
    let normalized_patch = normalize_schema_update_patch(patch)?;
    for (key, value) in normalized_patch {
        schema.insert(key, value);
    }
    document.schemas = Value::Array(schemas);
    Ok(json!({ "kind": "schema", "id": schema_id }))
}

fn normalize_schema_update_patch(
    patch: &serde_json::Map<String, Value>,
) -> Result<serde_json::Map<String, Value>, String> {
    let mut normalized = serde_json::Map::new();
    for (key, value) in patch {
        match key.as_str() {
            "id" => return Err("update_schema cannot change schema id".to_string()),
            "description" => {
                let description = value
                    .as_str()
                    .ok_or_else(|| "update_schema description must be a string".to_string())?;
                normalized.insert(
                    "description".to_string(),
                    Value::String(description.to_string()),
                );
            }
            other => return Err(format!("unsupported update_schema patch field: {other}")),
        }
    }
    Ok(normalized)
}

fn apply_rename_schema_operation(
    document: &mut MobpackDocument,
    operation: &serde_json::Map<String, Value>,
) -> Result<Value, String> {
    let schema_id = operation_schema_id(operation)?;
    let new_id = operation
        .get("new_id")
        .or_else(|| operation.get("newId"))
        .and_then(Value::as_str)
        .map(str::trim)
        .filter(|value| !value.is_empty())
        .ok_or_else(|| "rename_schema requires new_id".to_string())?
        .to_string();
    let mut schemas = document
        .schemas
        .as_array()
        .cloned()
        .unwrap_or_else(Vec::new);
    if schema_index_in_slice(&schemas, &new_id).is_some() {
        return Err(format!("schema already exists: {new_id}"));
    }
    let index = schema_index_in_slice(&schemas, &schema_id)
        .ok_or_else(|| format!("schema not found: {schema_id}"))?;
    schemas[index]["id"] = Value::String(new_id.clone());
    document.schemas = Value::Array(schemas);
    rewrite_member_schema_references(&mut document.members, &schema_id, &new_id);
    rewrite_adaptive_result_schema_references(document, &schema_id, &new_id);
    Ok(json!({ "kind": "schema", "id": new_id }))
}

fn apply_delete_schema_operation(
    document: &mut MobpackDocument,
    operation: &serde_json::Map<String, Value>,
) -> Result<Value, String> {
    let schema_id = operation_schema_id(operation)?;
    let removed_fields = schema_field_names(&document.schemas, &schema_id);
    let mut schemas = document
        .schemas
        .as_array()
        .cloned()
        .unwrap_or_else(Vec::new);
    let before = schemas.len();
    schemas.retain(|schema| {
        schema
            .get("id")
            .and_then(Value::as_str)
            .is_none_or(|id| id != schema_id)
    });
    if before == schemas.len() {
        return Err(format!("schema not found: {schema_id}"));
    }
    document.schemas = Value::Array(schemas);
    rewrite_member_schema_references(&mut document.members, &schema_id, "");
    rewrite_adaptive_result_schema_references(document, &schema_id, "");
    for field_name in removed_fields {
        rewrite_schema_field_references(document, &schema_id, &field_name, "");
    }
    Ok(json!({ "kind": null, "id": null }))
}

fn apply_add_schema_field_operation(
    document: &mut MobpackDocument,
    operation: &serde_json::Map<String, Value>,
) -> Result<Value, String> {
    let schema_id = operation_schema_id(operation)?;
    let mut schemas = document
        .schemas
        .as_array()
        .cloned()
        .unwrap_or_else(Vec::new);
    let index = schema_index_in_slice(&schemas, &schema_id)
        .ok_or_else(|| format!("schema not found: {schema_id}"))?;
    let schema = schemas[index]
        .as_object_mut()
        .ok_or_else(|| format!("schema is not an object: {schema_id}"))?;
    let fields = schema
        .entry("fields")
        .or_insert_with(|| Value::Array(Vec::new()))
        .as_array_mut()
        .ok_or_else(|| format!("schema fields is not an array: {schema_id}"))?;
    let field = operation
        .get("field")
        .cloned()
        .map(Ok)
        .unwrap_or_else(|| schema_field_from_draft(fields, "added_field"))?;
    let field_id = field
        .get("id")
        .and_then(Value::as_str)
        .map(str::trim)
        .filter(|value| !value.is_empty())
        .ok_or_else(|| "add_schema_field requires field.id".to_string())?
        .to_string();
    if fields.iter().any(|field| {
        field
            .get("id")
            .and_then(Value::as_str)
            .is_some_and(|id| id == field_id)
    }) {
        return Err(format!("schema field already exists: {field_id}"));
    }
    fields.push(field);
    document.schemas = Value::Array(schemas);
    Ok(json!({ "kind": "schema", "id": schema_id, "field_id": field_id }))
}

fn apply_update_schema_field_operation(
    document: &mut MobpackDocument,
    operation: &serde_json::Map<String, Value>,
) -> Result<Value, String> {
    let schema_id = operation_schema_id(operation)?;
    let field_id = operation_field_id(operation)?;
    let patch = operation
        .get("patch")
        .and_then(Value::as_object)
        .ok_or_else(|| "update_schema_field requires patch object".to_string())?;
    update_schema_field(document, &schema_id, &field_id, patch)
}

fn apply_rename_schema_field_operation(
    document: &mut MobpackDocument,
    operation: &serde_json::Map<String, Value>,
) -> Result<Value, String> {
    let schema_id = operation_schema_id(operation)?;
    let field_id = operation_field_id(operation)?;
    let new_name = operation
        .get("new_name")
        .or_else(|| operation.get("newName"))
        .and_then(Value::as_str)
        .map(str::trim)
        .filter(|value| !value.is_empty())
        .ok_or_else(|| "rename_schema_field requires new_name".to_string())?;
    let mut patch = serde_json::Map::new();
    patch.insert("name".to_string(), Value::String(new_name.to_string()));
    update_schema_field(document, &schema_id, &field_id, &patch)
}

fn apply_delete_schema_field_operation(
    document: &mut MobpackDocument,
    operation: &serde_json::Map<String, Value>,
) -> Result<Value, String> {
    let schema_id = operation_schema_id(operation)?;
    let field_id = operation_field_id(operation)?;
    let mut schemas = document
        .schemas
        .as_array()
        .cloned()
        .unwrap_or_else(Vec::new);
    let schema_index = schema_index_in_slice(&schemas, &schema_id)
        .ok_or_else(|| format!("schema not found: {schema_id}"))?;
    let fields = schemas[schema_index]
        .get_mut("fields")
        .and_then(Value::as_array_mut)
        .ok_or_else(|| format!("schema fields is not an array: {schema_id}"))?;
    let field_index = field_index_in_slice(fields, &field_id)
        .ok_or_else(|| format!("schema field not found: {field_id}"))?;
    let old_name = fields[field_index]
        .get("name")
        .and_then(Value::as_str)
        .unwrap_or_default()
        .to_string();
    fields.remove(field_index);
    document.schemas = Value::Array(schemas);
    if !old_name.is_empty() {
        rewrite_schema_field_references(document, &schema_id, &old_name, "");
    }
    Ok(json!({ "kind": "schema", "id": schema_id }))
}

fn apply_update_deploy_settings_operation(
    document: &mut MobpackDocument,
    operation: &serde_json::Map<String, Value>,
) -> Result<Value, String> {
    if let Some(deploy) = operation.get("deploy") {
        return Err(format!(
            "update_deploy_settings does not accept full deploy object; use field/value updates (received {})",
            value_kind(deploy)
        ));
    }
    let field = operation
        .get("field")
        .and_then(Value::as_str)
        .map(str::trim)
        .filter(|value| !value.is_empty())
        .ok_or_else(|| "update_deploy_settings requires field".to_string())?;
    let key = deploy_settings_field_key(field)
        .ok_or_else(|| format!("unsupported deploy settings field: {field}"))?;
    let value = normalize_deploy_settings_field_value(key, operation.get("value"))?;
    let mut settings = document
        .deploy
        .as_object()
        .cloned()
        .unwrap_or_else(serde_json::Map::new);
    settings.insert(key.to_string(), value);
    document.deploy = Value::Object(settings);
    Ok(operation_selection_or_clear(operation))
}

fn apply_update_mob_settings_operation(
    document: &mut MobpackDocument,
    operation: &serde_json::Map<String, Value>,
) -> Result<Value, String> {
    if let Some(settings) = operation
        .get("mob_settings")
        .or_else(|| operation.get("mobSettings"))
    {
        return Err(format!(
            "update_mob_settings does not accept full mob_settings object; use field/value updates (received {})",
            value_kind(settings)
        ));
    }
    let field = operation
        .get("field")
        .and_then(Value::as_str)
        .map(str::trim)
        .filter(|value| !value.is_empty())
        .ok_or_else(|| "update_mob_settings requires field".to_string())?;
    let key = mob_settings_field_key(field)
        .ok_or_else(|| format!("unsupported mob settings field: {field}"))?;
    let value = normalize_mob_settings_field_value(key, operation.get("value"))?;
    let mut settings = document
        .mob_settings
        .as_object()
        .cloned()
        .unwrap_or_else(serde_json::Map::new);
    settings.insert(key.to_string(), value);
    document.mob_settings = Value::Object(settings);
    Ok(operation_selection_or_clear(operation))
}

fn apply_update_role_wiring_operation(
    document: &mut MobpackDocument,
    operation: &serde_json::Map<String, Value>,
) -> Result<Value, String> {
    if let Some(settings) = operation
        .get("mob_settings")
        .or_else(|| operation.get("mobSettings"))
    {
        return Err(format!(
            "update_role_wiring does not accept full mob_settings object; use action updates (received {})",
            value_kind(settings)
        ));
    } else if let Some(role_wiring) = operation
        .get("role_wiring")
        .or_else(|| operation.get("roleWiring"))
    {
        return Err(format!(
            "update_role_wiring does not accept full role_wiring array; use action updates (received {})",
            value_kind(role_wiring)
        ));
    } else if let Some(action) = operation
        .get("action")
        .and_then(Value::as_str)
        .map(str::trim)
        .filter(|value| !value.is_empty())
    {
        apply_role_wiring_action(document, operation, action)?;
    } else {
        return Err("update_role_wiring requires action".to_string());
    }
    Ok(operation_selection_or_clear(operation))
}

fn deploy_settings_field_key(field: &str) -> Option<&'static str> {
    match field {
        "command" => Some("command"),
        "surface" => Some("surface"),
        "trustPolicy" | "trust_policy" => Some("trust_policy"),
        "model" => Some("model"),
        "maxDuration" | "max_duration" => Some("max_duration"),
        "maxToolCalls" | "max_tool_calls" => Some("max_tool_calls"),
        "maxTotalTokens" | "max_total_tokens" => Some("max_total_tokens"),
        "isolated" => Some("isolated"),
        "realm" => Some("realm"),
        "instance" => Some("instance"),
        "realmBackend" | "realm_backend" => Some("realm_backend"),
        "contextRoot" | "context_root" => Some("context_root"),
        "stateRoot" | "state_root" => Some("state_root"),
        "userConfigRoot" | "user_config_root" => Some("user_config_root"),
        "prompt" => Some("prompt"),
        _ => None,
    }
}

fn mob_settings_field_key(field: &str) -> Option<&'static str> {
    match field {
        "orchestrator" => Some("orchestrator"),
        "autoWireOrchestrator" | "auto_wire_orchestrator" => Some("autoWireOrchestrator"),
        "backendDefault" | "backend_default" => Some("backendDefault"),
        "externalAddressBase" | "external_address_base" => Some("externalAddressBase"),
        "advanced" => Some("advanced"),
        _ => None,
    }
}

fn normalize_deploy_settings_field_value(
    key: &str,
    value: Option<&Value>,
) -> Result<Value, String> {
    let value = value.unwrap_or(&Value::Null);
    match key {
        "command" => {
            let command = required_trimmed_string(value, "update_deploy_settings command")?;
            if command != "rkat mob run" {
                return Err(format!(
                    "deploy.command must be 'rkat mob run', got '{command}'"
                ));
            }
            Ok(Value::String(command))
        }
        "surface" => {
            optional_string_enum_value(value, "update_deploy_settings surface", &["cli", "rpc"])
        }
        "trust_policy" => optional_string_enum_value(
            value,
            "update_deploy_settings trustPolicy",
            &["permissive", "strict"],
        ),
        "realm_backend" => optional_string_enum_value(
            value,
            "update_deploy_settings realmBackend",
            &["jsonl", "sqlite"],
        ),
        "model" => {
            let model = optional_trimmed_string(value, "update_deploy_settings model")?;
            if let Value::String(model) = &model
                && !model.is_empty()
                && !available_model_ids().contains(model)
            {
                return Err(format!("unknown deploy model: {model}"));
            }
            Ok(model)
        }
        "max_tool_calls" | "max_total_tokens" => {
            optional_non_negative_integer_value(value, &format!("update_deploy_settings {key}"))
        }
        "isolated" => optional_bool_value(value, "update_deploy_settings isolated"),
        "max_duration" | "realm" | "instance" | "context_root" | "state_root"
        | "user_config_root" => {
            optional_trimmed_string(value, &format!("update_deploy_settings {key}"))
        }
        "prompt" => required_text_string(value, "update_deploy_settings prompt").map(Value::String),
        other => Err(format!("unsupported deploy settings field: {other}")),
    }
}

fn normalize_mob_settings_field_value(key: &str, value: Option<&Value>) -> Result<Value, String> {
    let value = value.unwrap_or(&Value::Null);
    match key {
        "orchestrator" | "externalAddressBase" => {
            optional_trimmed_string(value, &format!("update_mob_settings {key}"))
        }
        "autoWireOrchestrator" => {
            optional_bool_value(value, "update_mob_settings autoWireOrchestrator")
        }
        "backendDefault" => optional_string_enum_value(
            value,
            "update_mob_settings backendDefault",
            &["session", "external"],
        ),
        "advanced" => {
            if value.is_null() || value.is_object() {
                Ok(value.clone())
            } else {
                Err("update_mob_settings advanced must be a JSON object or null".to_string())
            }
        }
        other => Err(format!("unsupported mob settings field: {other}")),
    }
}

fn required_trimmed_string(value: &Value, context: &str) -> Result<String, String> {
    value
        .as_str()
        .map(str::trim)
        .filter(|value| !value.is_empty())
        .map(ToString::to_string)
        .ok_or_else(|| format!("{context} must be a non-empty string"))
}

// Required free text: must not be blank, but the stored value keeps the
// user's whitespace — these fields echo back into live inputs per keystroke.
fn required_text_string(value: &Value, context: &str) -> Result<String, String> {
    value
        .as_str()
        .filter(|value| !value.trim().is_empty())
        .map(ToString::to_string)
        .ok_or_else(|| format!("{context} must be a non-empty string"))
}

fn optional_trimmed_string(value: &Value, context: &str) -> Result<Value, String> {
    if value.is_null() {
        return Ok(Value::Null);
    }
    let text = value
        .as_str()
        .map(str::trim)
        .ok_or_else(|| format!("{context} must be a string or null"))?;
    Ok(Value::String(text.to_string()))
}

fn optional_string_enum_value(
    value: &Value,
    context: &str,
    allowed: &[&str],
) -> Result<Value, String> {
    if value.is_null() {
        return Ok(Value::Null);
    }
    let text = required_trimmed_string(value, context)?;
    if allowed.contains(&text.as_str()) {
        Ok(Value::String(text))
    } else {
        Err(format!(
            "{context} must be one of {}, got '{text}'",
            allowed.join(", ")
        ))
    }
}

fn optional_bool_value(value: &Value, context: &str) -> Result<Value, String> {
    if value.is_null() {
        return Ok(Value::Null);
    }
    value
        .as_bool()
        .map(Value::Bool)
        .ok_or_else(|| format!("{context} must be a boolean or null"))
}

fn optional_non_negative_integer_value(value: &Value, context: &str) -> Result<Value, String> {
    if value.is_null() {
        return Ok(Value::Null);
    }
    if let Some(value) = value.as_i64() {
        if value >= 0 {
            return Ok(Value::from(value));
        }
    } else if let Some(value) = value.as_u64() {
        return Ok(Value::from(value));
    } else if let Some(value) = value.as_f64()
        && value >= 0.0
        && value.fract() == 0.0
        && value <= i64::MAX as f64
    {
        return Ok(Value::from(value as i64));
    }
    Err(format!("{context} must be a non-negative integer or null"))
}

fn set_document_role_wiring(document: &mut MobpackDocument, role_wiring: Value) {
    let mut settings = document
        .mob_settings
        .as_object()
        .cloned()
        .unwrap_or_else(serde_json::Map::new);
    settings.insert("roleWiring".to_string(), role_wiring);
    document.mob_settings = Value::Object(settings);
}

fn apply_role_wiring_action(
    document: &mut MobpackDocument,
    operation: &serde_json::Map<String, Value>,
    action: &str,
) -> Result<(), String> {
    let mut wiring = editor_role_wiring_pairs(
        document
            .mob_settings
            .get("roleWiring")
            .or_else(|| document.mob_settings.get("role_wiring")),
    );
    let profiles = document_member_profiles(document);
    match action {
        "add" => {
            let first = profiles
                .first()
                .cloned()
                .ok_or_else(|| "update_role_wiring add requires at least one member".to_string())?;
            let second = profiles.get(1).cloned().unwrap_or_else(|| first.clone());
            wiring.push((first, second));
        }
        "delete" | "remove" => {
            let index = operation_index(operation, "update_role_wiring delete")?;
            if index >= wiring.len() {
                return Err(format!("role wiring index out of range: {index}"));
            }
            wiring.remove(index);
        }
        "set_source" | "set_target" => {
            let index = operation_index(operation, "update_role_wiring set")?;
            if index >= wiring.len() {
                return Err(format!("role wiring index out of range: {index}"));
            }
            let value = operation
                .get("value")
                .and_then(Value::as_str)
                .map(str::trim)
                .filter(|value| !value.is_empty())
                .ok_or_else(|| "update_role_wiring set requires value".to_string())?;
            if !profiles.is_empty() && !profiles.iter().any(|profile| profile == value) {
                return Err(format!(
                    "role wiring value is not a member profile: {value}"
                ));
            }
            if action == "set_source" {
                wiring[index].0 = value.to_string();
            } else {
                wiring[index].1 = value.to_string();
            }
        }
        other => return Err(format!("unsupported update_role_wiring action: {other}")),
    }
    set_document_role_wiring(
        document,
        Value::Array(
            wiring
                .into_iter()
                .filter(|(a, b)| !a.trim().is_empty() && !b.trim().is_empty())
                .map(|(a, b)| json!({ "a": a, "b": b }))
                .collect(),
        ),
    );
    Ok(())
}

fn operation_index(
    operation: &serde_json::Map<String, Value>,
    context: &str,
) -> Result<usize, String> {
    let index = operation
        .get("index")
        .and_then(Value::as_u64)
        .ok_or_else(|| format!("{context} requires index"))?;
    usize::try_from(index).map_err(|_| format!("{context} index is too large"))
}

fn document_member_profiles(document: &MobpackDocument) -> Vec<String> {
    document
        .members
        .as_array()
        .into_iter()
        .flatten()
        .map(editor_profile_name)
        .filter(|value| !value.is_empty())
        .collect()
}

fn editor_role_wiring_pairs(value: Option<&Value>) -> Vec<(String, String)> {
    value
        .and_then(Value::as_array)
        .into_iter()
        .flatten()
        .filter_map(|rule| {
            let a = rule.get("a").and_then(Value::as_str)?.trim();
            let b = rule.get("b").and_then(Value::as_str)?.trim();
            (!a.is_empty() && !b.is_empty()).then(|| (a.to_string(), b.to_string()))
        })
        .collect()
}

fn apply_add_agent_definition_operation(
    document: &mut MobpackDocument,
    operation: &serde_json::Map<String, Value>,
    runtime: Option<&MobpackRuntimeCatalogState>,
) -> Result<Value, String> {
    let definition_id = operation
        .get("definition_id")
        .or_else(|| operation.get("definitionId"))
        .and_then(Value::as_str)
        .map(str::trim)
        .filter(|value| !value.is_empty())
        .ok_or_else(|| "add_agent_definition requires definition_id".to_string())?;
    let definition = mobpack_agent_definition_by_id(definition_id, runtime)
        .ok_or_else(|| format!("unknown Meta agent definition: {definition_id}"))?;
    let member = member_from_agent_definition(&definition, &document.members)?;
    merge_agent_definition_schema(document, &definition);
    merge_agent_definition_skills(document, &definition);
    let mut members = document
        .members
        .as_array()
        .cloned()
        .unwrap_or_else(Vec::new);
    let member_id = member
        .get("id")
        .and_then(Value::as_str)
        .ok_or_else(|| "Meta agent definition produced member without id".to_string())?
        .to_string();
    members.push(member);
    document.members = Value::Array(members);
    Ok(json!({ "kind": "agent", "id": member_id }))
}

