    #[test]
    fn warns_on_unknown_editor_member_model_ref() {
        let mut document = document_with_member_catalog_refs(
            json!(["builtins", "comms"]),
            json!(["mob.workpad"]),
            json!([{
                "id": "meta/sample-mobpacks",
                "skills": [{
                    "id": "mob.workpad",
                    "source": "inline",
                    "content": "Keep the shared workpad concise and current."
                }]
            }]),
        );
        document.members[0]["model"] = json!("definitely-not-a-real-model");
        document.mob_toml = document.mob_toml.map(|text| {
            text.replace(
                "model = \"gpt-5.5\"",
                // meerkat 0.7 validates profile models fail-fast: an
                // uncatalogued model must be provider-annotated or it is a
                // definition-level error. The editor-catalog miss stays a
                // meta warning, which is what this test pins.
                "model = \"definitely-not-a-real-model\"\nprovider = \"openai\"",
            )
        });
        let result = validate_document(&document);

        assert!(result.ok, "{:?}", result.diagnostics);
        assert!(result.diagnostics.iter().any(|diagnostic| {
            diagnostic.code == "unknown_model_ref"
                && diagnostic.severity == "warning"
                && diagnostic.path.as_deref() == Some("members[0].model")
        }));
    }

