    #[test]
    fn schema_less_steps_export_text_output_format() {
        // A deployed flow with json-format steps and no schema fails every
        // free-text turn with "malformed JSON output", so the export default
        // must be schema-aware: text without a schema, implicit json with one.
        let document = document_with_expected_schema_ref();
        let validation = validate_document(&document);
        assert!(validation.ok, "{:?}", validation.diagnostics);
        let mob_toml = render_editor_document_mob_toml(&document).expect("rendered mob.toml");
        let plan_block = mob_toml
            .split("[flows.")
            .find(|block| block.contains("message = \"Plan\""))
            .expect("plan step block");
        assert!(
            plan_block.contains(r#"output_format = "text""#),
            "schema-less step must export text output format: {plan_block}"
        );
        let review_block = mob_toml
            .split("[flows.")
            .find(|block| block.contains("message = \"Review\"") && block.contains("steps"))
            .expect("review step block");
        assert!(
            review_block.contains(r#"expected_schema_ref = "schemas/reviewer.json""#),
            "{review_block}"
        );
        assert!(
            !review_block.contains("output_format ="),
            "schema-backed step keeps the implicit json runtime default: {review_block}"
        );
    }

    #[test]
    fn exports_expected_schema_ref_files_as_deployable_archive_members() {
        let mut document = document_with_expected_schema_ref();
        document.flow["steps"][0]["inputParams"] = json!([
            { "id": "p1", "name": "size", "type": "number", "required": true, "enumValues": [] },
            { "id": "p2", "name": "kind", "type": "enum", "required": true, "enumValues": ["docs", "code"] },
            { "id": "p3", "name": "tags", "type": "string[]", "required": false, "enumValues": [] },
            { "id": "p4", "name": "metadata", "type": "object", "required": false, "enumValues": [] }
        ]);
        document.flow["steps"][0]["fields"] =
            json!("size: number, kind: enum, tags: string[]?, metadata: object?");
        let validation = validate_document(&document);
        assert!(validation.ok, "{:?}", validation.diagnostics);
        let result = export_mobpack(&json!({ "document": document })).expect("export");
        assert!(result.validation.ok, "{:?}", result.validation.diagnostics);
        let exported_paths = result
            .source_files
            .iter()
            .map(|file| file.path.as_str())
            .collect::<Vec<_>>();
        assert!(exported_paths.contains(&"manifest.toml"));
        assert!(exported_paths.contains(&"definition.json"));
        assert!(exported_paths.contains(&"meta/editor.json"));
        assert!(exported_paths.contains(&"meta/mob.toml"));
        assert!(exported_paths.contains(&"schemas/reviewer.json"));
        assert!(exported_paths.contains(&"schemas/main-input.json"));
        let exported_mob_toml = result
            .source_files
            .iter()
            .find(|file| file.path == "meta/mob.toml")
            .expect("mob.toml source file");
        assert_eq!(exported_mob_toml.media_type, "text/toml");
        assert_eq!(
            exported_mob_toml.text.as_deref(),
            Some(result.mob_toml.as_str())
        );
        assert_eq!(
            exported_mob_toml.sha256,
            source_file_sha256(result.mob_toml.as_bytes())
        );
        let bytes = base64::engine::general_purpose::STANDARD
            .decode(&result.content_base64)
            .unwrap();
        let mut archive = tar::Archive::new(GzDecoder::new(bytes.as_slice()));
        let mut files = BTreeMap::new();
        for entry in archive.entries().unwrap() {
            let mut entry = entry.unwrap();
            let path = entry.path().unwrap().to_string_lossy().to_string();
            let mut bytes = Vec::new();
            entry.read_to_end(&mut bytes).unwrap();
            files.insert(path, bytes);
        }
        let schema = files
            .get("schemas/reviewer.json")
            .expect("reviewer schema archive member");
        let schema: Value = serde_json::from_slice(schema).expect("schema json");
        assert_eq!(schema["type"], "object");
        assert_eq!(
            schema["properties"]["verdict"]["enum"],
            json!(["green", "red"])
        );
        let input_schema = files
            .get("schemas/main-input.json")
            .expect("main input schema archive member");
        let input_schema: Value = serde_json::from_slice(input_schema).expect("input schema json");
        assert_eq!(input_schema["type"], "object");
        assert_eq!(input_schema["required"], json!(["size", "kind"]));
        assert_eq!(input_schema["properties"]["size"]["type"], "number");
        assert_eq!(
            input_schema["properties"]["kind"]["enum"],
            json!(["docs", "code"])
        );
        assert_eq!(input_schema["properties"]["tags"]["type"], "array");
        assert_eq!(
            input_schema["properties"]["tags"]["items"]["type"],
            "string"
        );
        assert_eq!(input_schema["properties"]["metadata"]["type"], "object");
    }

    /// The skills catalog reads each filesystem `SKILL.md` with meerkat's own
    /// parser, keyed by its directory slug. A skill the parser accepts shows
    /// its parsed description (a block scalar's text, not `|`) and
    /// capabilities. One the parser refuses stays listed and deployable (a
    /// mobpack hands its text over unparsed) and names the typed refusal.
    #[test]
    fn skill_catalog_reads_each_skill_with_meerkats_parser() {
        let dir = tempfile::tempdir().expect("tempdir");
        for (slug, content) in [
            (
                "block-desc",
                "---\nname: block-desc\ndescription: |\n  Line one\n  Line two\nrequires_capabilities: [builtins]\n---\n\n# Body\n",
            ),
            ("no-frontmatter", "Just a body.\n"),
            (
                "duplicate-key",
                "---\nname: duplicate-key\ndescription: one\ndescription: two\n---\n",
            ),
            (
                "end-marker",
                "---\nname: end-marker\ndescription: d\n...\nnot: parsed\n---\n",
            ),
            ("wrong-name", "---\nname: other-name\ndescription: d\n---\n"),
            ("Bad_Slug", "---\nname: bad-slug\ndescription: d\n---\n"),
        ] {
            let skill_dir = dir.path().join(slug);
            std::fs::create_dir_all(&skill_dir).expect("skill dir");
            std::fs::write(skill_dir.join("SKILL.md"), content).expect("write skill");
        }

        let skills = discover_skills_in_dir(dir.path());
        let listed = |id: &str| {
            skills
                .iter()
                .find(|skill| skill["id"] == id)
                .unwrap_or_else(|| panic!("{id} is not listed: {skills:#?}"))
                .clone()
        };

        let accepted = listed("block-desc");
        assert_eq!(accepted["label"], "block-desc", "{accepted:#}");
        assert_eq!(accepted["desc"], "Line one\nLine two\n", "{accepted:#}");
        assert_eq!(accepted["requires_capabilities"], json!(["builtins"]));
        assert_eq!(accepted["deployability"]["deployable"], json!(true));
        assert!(accepted.get("skill_refusal").is_none(), "{accepted:#}");

        for (id, kind) in [
            ("no-frontmatter", "skill_document_refused"),
            ("duplicate-key", "skill_document_refused"),
            ("end-marker", "skill_document_refused"),
            ("wrong-name", "skill_document_refused"),
            ("Bad_Slug", "invalid_skill_slug"),
        ] {
            let refused = listed(id);
            assert_eq!(
                refused["deployability"]["deployable"],
                json!(true),
                "{refused:#}"
            );
            assert_eq!(refused["skill_refusal"]["kind"], kind, "{refused:#}");
            assert!(
                refused["skill_refusal"]["error"]
                    .as_str()
                    .is_some_and(|error| error.starts_with("skill parse failed: ")),
                "{refused:#}"
            );
            assert!(
                refused["path"]
                    .as_str()
                    .is_some_and(|path| path.ends_with("SKILL.md")),
                "{refused:#}"
            );
            assert_eq!(refused["label"], id, "{refused:#}");
            assert_eq!(refused["requires_capabilities"], json!([]), "{refused:#}");
        }
    }

    #[test]
    fn exports_selected_filesystem_skills_as_packed_mobpack_members() {
        let dir = tempfile::tempdir().expect("tempdir");
        let skill_path = dir.path().join("SKILL.md");
        std::fs::write(&skill_path, "Use the real Meta platform contract.").expect("write skill");

        let mut document = document_with_expected_schema_ref();
        document.mob_toml = None;
        document.members.as_array_mut().unwrap()[0]["skills"] = json!(["mob.platform"]);
        document.skill_realms = json!([{
            "id": "local/filesystem",
            "label": "Local filesystem",
            "source": "filesystem",
            "skills": [{
                "id": "mob.platform",
                "label": "Meta Platform",
                "source": "path",
                "path": skill_path
            }]
        }]);

        let result =
            with_host_path_skill_reads(|| export_mobpack(&json!({ "document": document })))
                .expect("export");
        assert!(result.validation.ok, "{:?}", result.validation.diagnostics);
        assert!(result.mob_toml.contains(r#"[skills."mob.platform"]"#));
        assert!(result.mob_toml.contains(r#"source = "path""#));
        assert!(
            result
                .mob_toml
                .contains(r#"path = "skills/mob-platform.md""#)
        );
        assert!(
            !result
                .mob_toml
                .contains(dir.path().to_string_lossy().as_ref())
        );
        let exported_skill = result
            .source_files
            .iter()
            .find(|file| file.path == "skills/mob-platform.md")
            .expect("packed skill source file");
        assert_eq!(exported_skill.media_type, "text/markdown");
        assert_eq!(
            exported_skill.text.as_deref(),
            Some("Use the real Meta platform contract.")
        );

        let bytes = base64::engine::general_purpose::STANDARD
            .decode(&result.content_base64)
            .unwrap();
        let mut archive = tar::Archive::new(GzDecoder::new(bytes.as_slice()));
        let mut files = BTreeMap::new();
        for entry in archive.entries().unwrap() {
            let mut entry = entry.unwrap();
            let path = entry.path().unwrap().to_string_lossy().to_string();
            let mut bytes = Vec::new();
            entry.read_to_end(&mut bytes).unwrap();
            files.insert(path, bytes);
        }
        assert_eq!(
            String::from_utf8(files["skills/mob-platform.md"].clone()).unwrap(),
            "Use the real Meta platform contract."
        );

        let imported =
            import_mobpack(&json!({ "content_base64": result.content_base64 })).expect("import");
        let imported_skill = imported["document"]["skill_realms"]
            .as_array()
            .unwrap()
            .iter()
            .flat_map(|realm| realm["skills"].as_array().unwrap())
            .find(|skill| skill["id"] == "mob.platform")
            .expect("imported skill");
        assert_eq!(
            imported_skill["content"],
            json!("Use the real Meta platform contract.")
        );
    }

