    #[test]
    fn guarded_document_actions_reject_stale_draft_revision() {
        let dir = tempfile::tempdir().expect("tempdir");
        let store_path = dir.path().join("drafts.json");
        let output_dir = dir.path().join("deploy");
        let saved = save_mobpack_draft(&json!({
            "store_path": store_path,
            "id": "action_guard",
            "document": valid_document(),
        }))
        .expect("save guarded draft");
        let document = saved["row"]["document"].clone();

        let stale_params = json!({
            "store_path": store_path,
            "id": "action_guard",
            "expected_revision": 0,
            "document": document,
            "output_dir": output_dir,
            "prompt": "Reply with exactly OK.",
            "execute": false,
        });

        let validation = validate_mobpack(&stale_params).expect_err("stale validate must fail");
        assert!(
            validation.contains("meta/mobpacks/validate draft revision conflict for action_guard"),
            "{validation}"
        );

        let source = source_mobpack(&stale_params).expect_err("stale source must fail");
        assert!(
            source.contains("meta/mobpacks/source draft revision conflict for action_guard"),
            "{source}"
        );

        let graph_projection =
            graph_projection_mobpack(&stale_params).expect_err("stale graph projection must fail");
        assert!(
            graph_projection.contains(
                "meta/mobpacks/graph_projection draft revision conflict for action_guard"
            ),
            "{graph_projection}"
        );

        let graph_to_flow =
            graph_to_flow_mobpack(&stale_params).expect_err("stale graph-to-flow must fail");
        assert!(
            graph_to_flow
                .contains("meta/mobpacks/graph_to_flow draft revision conflict for action_guard"),
            "{graph_to_flow}"
        );

        let exported = export_mobpack(&stale_params).expect_err("stale export must fail");
        assert!(
            exported.contains("meta/mobpacks/export draft revision conflict for action_guard"),
            "{exported}"
        );

        let preview =
            deploy_command_preview(&stale_params).expect_err("stale deploy command must fail");
        assert!(
            preview
                .contains("meta/mobpacks/deploy_command draft revision conflict for action_guard"),
            "{preview}"
        );

        let deployed = deploy_mobpack(&stale_params).expect_err("stale deploy must fail");
        assert!(
            deployed.contains("meta/mobpacks/deploy draft revision conflict for action_guard"),
            "{deployed}"
        );

        // The editor document the draft opens with: `get` re-imports its
        // archive; the save reply carries the draft as stored.
        let opened = get_mobpack_draft(&json!({
            "store_path": store_path,
            "id": "action_guard"
        }))
        .expect("get guarded draft");
        let fresh_params = json!({
            "store_path": store_path,
            "id": "action_guard",
            "expected_revision": 1,
            "expected_etag": "action_guard:1",
            "document": opened["row"]["document"].clone(),
            "output_dir": dir.path().join("fresh-deploy"),
            "prompt": "Reply with exactly OK.",
            "execute": false,
        });
        assert!(validate_mobpack(&fresh_params).expect("fresh validate").ok);
        assert!(
            source_mobpack(&fresh_params)
                .expect("fresh source")
                .source_files
                .iter()
                .any(|file| file.path.ends_with("mob.toml"))
        );
        assert!(
            graph_projection_mobpack(&fresh_params).expect("fresh graph projection")["validation"]
                ["ok"]
                .as_bool()
                .unwrap_or(false)
        );
        assert!(
            graph_to_flow_mobpack(&fresh_params).expect("fresh graph-to-flow")["ok"]
                .as_bool()
                .unwrap_or(false)
        );
        assert!(
            export_mobpack(&fresh_params)
                .expect("fresh export")
                .validation
                .ok
        );
        assert!(
            deploy_command_preview(&fresh_params)
                .expect("fresh deploy command")
                .validation
                .ok
        );
        assert!(
            deploy_mobpack(&fresh_params)
                .expect("fresh deploy")
                .validation
                .ok
        );
    }

    #[test]
    fn mobpack_draft_registry_defaults_to_durable_state_path() {
        // The layered `$XDG_STATE_HOME`/`$HOME` rules are storage_layout's
        // (tested there); mobpack only appends its feature-owned file name
        // under the gateway home, and refuses when neither root exists.
        let Ok(path) = default_mobpack_draft_store_path() else {
            // Only an unadopted predecessor home in the ambient environment
            // refuses; that refusal is covered by the storage_predecessor
            // tests.
            return;
        };
        assert_eq!(
            path.file_name().and_then(|name| name.to_str()),
            Some(MOBPACK_DRAFT_STORE_FILENAME)
        );
        if let Ok(home) = crate::storage_layout::default_gateway_home() {
            assert_eq!(path, home.join(MOBPACK_DRAFT_STORE_FILENAME));
            assert!(
                !path.starts_with(std::env::temp_dir()) || home.starts_with(std::env::temp_dir()),
                "draft registry must not default to temp storage when a state root is available"
            );
        }
    }

    #[test]
    fn mobpack_draft_registry_persists_saved_editor_documents() {
        let dir = tempfile::tempdir().expect("tempdir");
        let store_path = dir.path().join("drafts.json");
        let mut document = valid_document();
        document.name = "Registry Draft".to_string();

        let saved = save_mobpack_draft(&json!({
            "store_path": store_path,
            "id": "registry_draft",
            "document": document,
            "stage": "draft",
            "trigger": "manual save"
        }))
        .expect("save draft");
        assert!(
            saved["row"]["document"]["mob_toml"]
                .as_str()
                .is_some_and(|text| text.contains("[mob]")),
            "saved registry document must persist the server-rendered canonical mob.toml"
        );
        assert_eq!(saved["source"], json!("meta/mobpacks/save"));
        assert_eq!(saved["row"]["id"], json!("registry_draft"));
        assert_eq!(saved["row"]["revision"], json!(1));
        assert_eq!(saved["row"]["draft_revision"], json!(1));
        assert_eq!(saved["row"]["draft_etag"], json!("registry_draft:1"));
        assert_eq!(saved["row"]["document"]["name"], json!("Registry Draft"));
        assert_eq!(saved["row"]["document_kind"], json!("editor_projection"));
        // Only `get` re-imports the archive; the save reply carries the
        // draft as stored.
        assert_eq!(saved["row"]["document_authority"], Value::Null);
        assert_eq!(saved["row"]["stage"], json!("valid"));
        assert_eq!(saved["row"]["artifact"]["kind"], json!("mobpack_archive"));
        assert_eq!(saved["row"]["artifact"]["deployable"], json!(true));
        assert_eq!(
            saved["row"]["artifact"]["media_type"],
            json!(MOBPACK_MEDIA_TYPE)
        );
        assert!(
            saved["row"]["artifact"]["content_base64"]
                .as_str()
                .is_some_and(|value| !value.is_empty())
        );
        assert!(
            saved["row"]["artifact"]["pack_sha256"]
                .as_str()
                .is_some_and(|value| !value.is_empty())
        );

        let listed =
            list_mobpack_drafts(&json!({ "store_path": store_path })).expect("list drafts");
        assert_eq!(listed["source"], json!("meta/mobpacks/list"));
        assert_eq!(listed["rows"].as_array().expect("rows").len(), 1);
        assert_eq!(listed["rows"][0]["id"], json!("registry_draft"));
        assert_eq!(listed["rows"][0]["revision"], json!(1));
        assert_eq!(listed["rows"][0]["draft_etag"], json!("registry_draft:1"));
        assert_eq!(listed["rows"][0]["document_authority"], Value::Null);
        // A list carries summaries; the archive comes with the draft.
        assert_eq!(listed["rows"][0].get("artifact"), None);

        let fetched = get_mobpack_draft(&json!({
            "store_path": store_path,
            "id": "registry_draft"
        }))
        .expect("get draft");
        assert_eq!(fetched["row"]["document"]["mob_id"], json!("review-pack"));
        assert_eq!(fetched["row"]["revision"], json!(1));
        assert_eq!(fetched["row"]["draft_etag"], json!("registry_draft:1"));
        assert_eq!(fetched["row"]["document_source"], json!("mobpack_archive"));
        assert_eq!(fetched["row"]["document_authority"], json!("artifact"));
        assert_eq!(fetched["row"]["artifact"]["kind"], json!("mobpack_archive"));

        let deleted = delete_mobpack_draft(&json!({
            "store_path": store_path,
            "id": "registry_draft"
        }))
        .expect("delete draft");
        assert_eq!(deleted["deleted"], json!(true));
        assert_eq!(deleted["rows"].as_array().expect("rows").len(), 0);
    }

    #[test]
    fn mobpack_draft_registry_rejects_stale_expected_revision() {
        let dir = tempfile::tempdir().expect("tempdir");
        let store_path = dir.path().join("drafts.json");
        let mut document = valid_document();
        document.name = "Revision One".to_string();

        let first = save_mobpack_draft(&json!({
            "store_path": store_path,
            "id": "revision_guard",
            "document": document,
        }))
        .expect("initial save");
        assert_eq!(first["row"]["revision"], json!(1));
        assert_eq!(first["row"]["draft_etag"], json!("revision_guard:1"));

        let mut updated = valid_document();
        updated.name = "Revision Two".to_string();
        let second = save_mobpack_draft(&json!({
            "store_path": store_path,
            "id": "revision_guard",
            "document": updated,
            "expected_revision": 1,
        }))
        .expect("second save");
        assert_eq!(second["row"]["revision"], json!(2));
        assert_eq!(second["row"]["draft_etag"], json!("revision_guard:2"));

        let mut stale = valid_document();
        stale.name = "Stale Revision".to_string();
        let error = save_mobpack_draft(&json!({
            "store_path": store_path,
            "id": "revision_guard",
            "document": stale,
            "expected_revision": 1,
        }))
        .expect_err("stale save must fail");
        assert!(
            error.contains(
                "mobpack draft revision conflict for revision_guard: expected 1, found 2"
            ),
            "{error}"
        );

        let fetched = get_mobpack_draft(&json!({
            "store_path": store_path,
            "id": "revision_guard"
        }))
        .expect("get draft");
        assert_eq!(fetched["row"]["revision"], json!(2));
        assert_eq!(fetched["row"]["draft_etag"], json!("revision_guard:2"));
        assert_eq!(fetched["row"]["document"]["name"], json!("Revision Two"));
    }

    #[test]
    fn mobpack_draft_registry_rejects_stale_delete_revision() {
        let dir = tempfile::tempdir().expect("tempdir");
        let store_path = dir.path().join("drafts.json");

        let saved = save_mobpack_draft(&json!({
            "store_path": store_path,
            "id": "delete_guard",
            "document": valid_document(),
        }))
        .expect("save draft");
        assert_eq!(saved["row"]["revision"], json!(1));

        let stale = delete_mobpack_draft(&json!({
            "store_path": store_path,
            "id": "delete_guard",
            "expected_revision": 0,
        }))
        .expect_err("stale delete must fail");
        assert!(
            stale.contains("meta/mobpacks/delete draft revision conflict for delete_guard"),
            "{stale}"
        );

        let deleted = delete_mobpack_draft(&json!({
            "store_path": store_path,
            "id": "delete_guard",
            "expected_revision": 1,
            "expected_etag": "delete_guard:1",
        }))
        .expect("guarded delete");
        assert_eq!(deleted["deleted"], json!(true));
    }

    #[test]
    fn mobpack_draft_registry_reopens_deployable_artifact_over_stale_projection() {
        let dir = tempfile::tempdir().expect("tempdir");
        let store_path = dir.path().join("drafts.json");
        let mut document = valid_document();
        document.name = "Artifact Authority".to_string();

        let saved = save_mobpack_draft(&json!({
            "store_path": store_path,
            "id": "artifact_authority",
            "document": document
        }))
        .expect("save draft");
        let pack_sha256 = saved["row"]["artifact"]["pack_sha256"].clone();

        let mut rows = read_mobpack_draft_store(&store_path).expect("read draft store");
        let row = rows
            .get_mut("artifact_authority")
            .expect("stored draft row");
        row["document"]["mob_id"] = json!("stale-registry-projection");
        row["document"]["name"] = json!("Stale Registry Projection");
        row["validation"] = json!({
            "ok": false,
            "diagnostics": [],
            "display_rows": [{ "kind": "crit", "head": "stale projection", "sub": "", "meta": "" }],
            "flow_ids": [],
            "validation_source": "caller",
            "deploy_command": "stale"
        });
        write_mobpack_draft_store(&store_path, &rows).expect("write stale draft store");

        // A list carries summaries; only `get` returns a draft's document,
        // re-imported from its archive.
        let listed =
            list_mobpack_drafts(&json!({ "store_path": store_path })).expect("list drafts");
        let listed_row = &listed["rows"][0];
        assert_eq!(listed_row["document_authority"], Value::Null);
        assert_eq!(
            (listed_row.get("document"), listed_row.get("artifact")),
            (None, None)
        );

        let fetched = get_mobpack_draft(&json!({
            "store_path": store_path,
            "id": "artifact_authority"
        }))
        .expect("get draft");
        assert_eq!(fetched["row"]["artifact"]["pack_sha256"], pack_sha256);
        assert_eq!(fetched["row"]["document_source"], json!("mobpack_archive"));
        assert_eq!(fetched["row"]["document_authority"], json!("artifact"));
        assert_eq!(fetched["row"]["document"]["mob_id"], json!("review-pack"));
        assert_eq!(fetched["row"]["validation"]["ok"], json!(true));
    }

