    #[test]
    fn runtime_bound_apply_operation_uses_runtime_catalog_snapshot() {
        let runtime = MobpackRuntimeCatalogState {
            loaded_modules: vec!["editor-host".to_string()],
            runtime_methods: vec!["meta/mobpacks/apply_operation".to_string()],
            has_contact_directory: true,
            has_peer_mob_handles: false,
            has_inproc_contacts: false,
            runtime_flow_rows: Vec::new(),
            runtime_agent_definition_sources: Vec::new(),
            runtime_skill_realms: Vec::new(),
        };
        let runtime_catalogs = mobpack_catalogs_response_with_runtime(Some(&runtime));
        let standalone_catalogs = mobpack_catalogs_response();
        let runtime_mob_tool = runtime_catalogs["tool_catalog"]
            .as_array()
            .expect("runtime tool catalog")
            .iter()
            .find(|tool| tool["id"] == "mob")
            .expect("mob tool");
        assert_eq!(
            runtime_mob_tool["runtime_availability"]["available"],
            json!(false)
        );
        assert_eq!(
            runtime_mob_tool["runtimeAvailability"]["available"],
            json!(false)
        );
        let runtime_planner_definition = runtime_catalogs["agent_definitions"]
            .as_array()
            .expect("agent definitions")
            .iter()
            .find(|definition| {
                definition["role"] == "planner"
                    && definition["sourceOrigin"] == "meta/authoring-agent-definitions"
            })
            .expect("runtime authoring planner definition");
        let runtime_planner_mob_tool = runtime_planner_definition["toolDefinitions"]
            .as_array()
            .expect("planner tool definitions")
            .iter()
            .find(|tool| tool["id"] == "mob")
            .expect("planner mob tool definition");
        assert_eq!(
            runtime_planner_mob_tool["runtime_availability"]["available"],
            json!(false)
        );
        assert_eq!(
            runtime_planner_mob_tool["runtimeAvailability"]["state"],
            json!("unavailable")
        );
        let runtime_agent_definition = runtime_catalogs["agent_definitions"]
            .as_array()
            .expect("agent definitions")
            .iter()
            .find(|definition| {
                definition["role"] == "agent"
                    && definition["sourceOrigin"] == "meta/authoring-agent-definitions"
            })
            .expect("blank authoring agent definition");
        let runtime_agent_builtins = runtime_agent_definition["toolDefinitions"]
            .as_array()
            .expect("agent tool definitions")
            .iter()
            .find(|tool| tool["id"] == "builtins")
            .expect("agent builtins tool definition");
        assert_eq!(
            runtime_agent_builtins["runtime_availability"]["state"],
            json!("available")
        );
        let runtime_snapshot = runtime_catalogs["catalog_snapshot"]["id"]
            .as_str()
            .expect("runtime snapshot id");
        assert_ne!(
            runtime_snapshot,
            standalone_catalogs["catalog_snapshot"]["id"]
                .as_str()
                .expect("standalone snapshot id")
        );
        let document: MobpackDocument =
            serde_json::from_value(runtime_catalogs["blank_mobpack"]["document"].clone())
                .expect("blank document");

        let standalone_add_request = json!({
            "document": document,
            "expected_catalog_snapshot_id": runtime_snapshot,
            "operation": {
                "type": "add_agent_definition",
                "definition_id": runtime_agent_definition["id"].clone()
            }
        });
        let standalone_rejects_runtime_snapshot =
            apply_mobpack_authoring_operation(&standalone_add_request)
                .expect_err("standalone apply_operation must not accept runtime snapshot");
        assert!(
            standalone_rejects_runtime_snapshot
                .contains("catalog snapshot conflict for add_agent_definition"),
            "{standalone_rejects_runtime_snapshot}"
        );

        let added = apply_mobpack_authoring_operation_with_runtime(
            &json!({
                "document": document,
                "expected_catalog_snapshot_id": runtime_snapshot,
                "operation": {
                    "type": "add_agent_definition",
                    "definition_id": runtime_agent_definition["id"].clone()
                }
            }),
            Some(&runtime),
        )
        .expect("runtime apply_operation accepts runtime agent catalog snapshot");
        let member_id = added["selection"]["id"]
            .as_str()
            .expect("member id")
            .to_string();

        let tool_added = apply_mobpack_authoring_operation_with_runtime(
            &json!({
                "document": added["document"].clone(),
                "expected_catalog_snapshot_id": runtime_snapshot,
                "operation": {
                    "type": "add_member_tool",
                    "member_id": member_id,
                    "tool_id": "shell"
                }
            }),
            Some(&runtime),
        )
        .expect("runtime apply_operation accepts runtime tool catalog snapshot");
        assert_eq!(tool_added["operation"], json!("add_member_tool"));

        let unavailable_tool = apply_mobpack_authoring_operation_with_runtime(
            &json!({
                "document": tool_added["document"].clone(),
                "expected_catalog_snapshot_id": runtime_snapshot,
                "operation": {
                    "type": "add_member_tool",
                    "member_id": member_id,
                    "tool_id": "mob"
                }
            }),
            Some(&runtime),
        )
        .expect_err("runtime-unavailable tool must fail");
        assert!(
            unavailable_tool.contains("Meta tool is unavailable in current runtime: mob"),
            "{unavailable_tool}"
        );

        let cross_mob_runtime = MobpackRuntimeCatalogState {
            loaded_modules: vec!["editor-host".to_string()],
            runtime_methods: vec![
                "meta/mobpacks/apply_operation".to_string(),
                "meta/cross_mob/wire".to_string(),
                "meta/cross_mob/unwire".to_string(),
                "meta/cross_mob/send".to_string(),
            ],
            has_contact_directory: true,
            has_peer_mob_handles: true,
            has_inproc_contacts: true,
            runtime_flow_rows: Vec::new(),
            runtime_agent_definition_sources: Vec::new(),
            runtime_skill_realms: Vec::new(),
        };
        let cross_mob_catalogs = mobpack_catalogs_response_with_runtime(Some(&cross_mob_runtime));
        let cross_mob_tool = cross_mob_catalogs["tool_catalog"]
            .as_array()
            .expect("cross-mob tool catalog")
            .iter()
            .find(|tool| tool["id"] == "mob")
            .expect("mob tool");
        assert_eq!(
            cross_mob_tool["runtime_availability"]["available"],
            json!(true)
        );

        let skill_toggled = apply_mobpack_authoring_operation_with_runtime(
            &json!({
                "document": tool_added["document"].clone(),
                "expected_catalog_snapshot_id": runtime_snapshot,
                "operation": {
                    "type": "toggle_member_skill",
                    "member_id": member_id,
                    "skill_id": "mob.authoring.review"
                }
            }),
            Some(&runtime),
        )
        .expect("runtime apply_operation accepts runtime skill catalog snapshot");
        assert_eq!(skill_toggled["operation"], json!("toggle_member_skill"));
        let copied_skill = skill_toggled["document"]["skill_realms"]
            .as_array()
            .expect("skill realms")
            .iter()
            .flat_map(|realm| realm["skills"].as_array().into_iter().flatten())
            .find(|skill| skill["id"] == "mob.authoring.review")
            .expect("runtime catalog skill copied into document");
        assert_eq!(
            copied_skill["provenance"]["catalog"],
            json!("meta/skills/catalog")
        );
        assert_eq!(
            copied_skill["sourceMobpack"],
            json!("meta_authoring_profiles")
        );
    }

    #[test]
    fn runtime_flow_registry_rows_project_each_loaded_runtime_flow() {
        let definition = MobDefinition::from_toml(
            r#"
[mob]
id = "runtime-editor-proof"

[profiles.worker]
model = "gpt-5.5"
runtime_mode = "turn_driven"

[profiles.worker.tools]
builtins = true

[flows.main]
description = "Run the main runtime flow."

[flows.main.steps.work]
role = "worker"
message = "Work."

[flows.main.root.nodes.node_work]
kind = "step"
step_id = "work"
depends_on = []
depends_on_mode = "all"

[flows.audit]
description = "Run the audit runtime flow."

[flows.audit.steps.audit]
role = "worker"
message = "Audit."

[flows.audit.root.nodes.node_audit]
kind = "step"
step_id = "audit"
depends_on = []
depends_on_mode = "all"
"#,
        )
        .expect("runtime definition");

        let rows = runtime_flow_registry_rows_from_definition(&definition);
        assert_eq!(rows.len(), 2);
        assert_eq!(
            rows.iter()
                .map(|row| row["runtime_flow_id"].as_str().unwrap_or_default())
                .collect::<Vec<_>>(),
            vec!["audit", "main"]
        );
        for row in &rows {
            assert_eq!(row["source"], json!("meta/runtime/flow_projection"));
            assert_eq!(row["runtime_projection"], json!(true));
            assert_eq!(row["validation"]["ok"], json!(true));
            assert_eq!(row["document"]["mob_id"], json!("runtime-editor-proof"));
            assert_eq!(row["document"]["flow"]["name"], row["runtime_flow_id"]);
        }

        let runtime = MobpackRuntimeCatalogState {
            loaded_modules: vec!["runtime-editor-proof".to_string()],
            runtime_methods: vec!["meta/list_flows".to_string()],
            has_contact_directory: false,
            has_peer_mob_handles: false,
            has_inproc_contacts: false,
            runtime_flow_rows: rows.clone(),
            runtime_agent_definition_sources: Vec::new(),
            runtime_skill_realms: Vec::new(),
        };
        let catalogs = mobpack_catalogs_response_with_runtime(Some(&runtime));
        assert_eq!(catalogs["runtime_flows"], json!(rows));
        assert_eq!(
            catalogs["runtime_flows"][0]["provenance"]["catalog"],
            json!("meta/runtime/flow_projection")
        );
    }

