    #[test]
    fn reports_missing_rkat_mob_run_as_deploy_result() {
        let dir = tempfile::tempdir().expect("tempdir");
        let missing_rkat = dir.path().join("missing-rkat");

        let result = deploy_mobpack(&json!({
            "document": valid_document(),
            "output_dir": dir.path(),
            "prompt": "Reply with exactly OK.",
            "rkat_bin": missing_rkat,
            "execute": true
        }))
        .expect("deploy result");

        assert!(result.executed);
        assert!(!result.success);
        assert_eq!(result.status_code, None);
        assert!(result.validation.ok, "{:?}", result.validation.diagnostics);
        assert!(std::path::Path::new(&result.pack_path).exists());
        assert!(
            result
                .stderr
                .as_deref()
                .unwrap_or_default()
                .contains("failed to run rkat mob run")
        );
        assert!(result.plan_trace.iter().any(|row| {
            row["head"]
                .as_str()
                .unwrap_or_default()
                .starts_with("MOBPACK ·")
        }));
        assert!(result.display_rows.iter().any(|row| {
            row.kind == "crit"
                && row.head == "rkat mob run failed"
                && row.sub.contains("rkat mob run")
        }));
        assert!(result.display_rows.iter().any(|row| {
            row.kind == "warn"
                && row.head == "rkat output"
                && row.sub.contains("failed to run rkat mob run")
        }));
    }

    #[test]
    fn imports_mobpack_payload_without_runtime_mutation() {
        let params = match std::env::var("META_MOBPACK_IMPORT_IN") {
            Ok(path) => serde_json::from_str(
                &std::fs::read_to_string(path).expect("read editor mobpack import params"),
            )
            .expect("parse editor mobpack import params"),
            Err(_) => json!({ "mob_toml": importable_mob_toml() }),
        };
        let result = import_mobpack(&params).expect("import");
        assert_eq!(result["validation"]["ok"], true);
        assert!(!result["document"]["members"].as_array().unwrap().is_empty());
        if let Ok(path) = std::env::var("META_MOBPACK_IMPORT_OUT") {
            std::fs::write(path, serde_json::to_vec_pretty(&result).unwrap())
                .expect("write imported mobpack result");
        }
    }

    #[test]
    fn catalogs_response_exposes_filesystem_skill_catalog() {
        let schema = mobpack_schema_response();
        let catalogs = mobpack_catalogs_response();
        assert!(
            schema.get("starter_skills").is_none(),
            "starter skills must be exposed through skill_realms, not a duplicate fallback catalog"
        );
        assert!(
            schema.get("skill_realms").is_none(),
            "dynamic skill realms must be loaded through meta/mobpacks/catalogs"
        );
        let realms = catalogs["skill_realms"].as_array().expect("skill realms");
        let meerkat_meta = realms
            .iter()
            .find(|realm| realm["source"] == "filesystem")
            .and_then(|realm| realm["skills"].as_array())
            .and_then(|skills| skills.iter().find(|skill| skill["id"] == "meerkat-meta"))
            .expect("meerkat-meta filesystem skill");
        assert_eq!(meerkat_meta["source"], "path");
        assert_eq!(meerkat_meta["origin"], "filesystem");
        assert!(
            meerkat_meta["path"]
                .as_str()
                .is_some_and(|path| path.ends_with("SKILL.md"))
        );
        assert!(
            realms.iter().all(|realm| realm["source"] != "starter"),
            "skill realms must come from filesystem or authoring mobpacks, not starter mocks"
        );
        assert!(
            realms.iter().all(|realm| {
                realm["id"] != "meta/sample-mobpacks" && realm["source"] != "meta/sample-mobpack"
            }),
            "global skill catalog must not leak sample mobpack skill realms"
        );
        let authoring_realm = realms
            .iter()
            .find(|realm| realm["id"] == "meta/authoring-agent-definitions")
            .expect("authoring agent definition skill realm");
        assert_eq!(authoring_realm["source"], "meta/authoring-agent-definition");
        assert_eq!(
            authoring_realm["sourceDocumentPath"],
            "authoring_mobpacks[].document.skill_realms[]"
        );
        let authoring_skill = authoring_realm["skills"]
            .as_array()
            .expect("authoring realm skills")
            .iter()
            .find(|skill| skill["id"] == "mob.authoring.review")
            .expect("authoring review skill");
        assert_eq!(
            authoring_skill["origin"],
            "meta/authoring-agent-definitions"
        );
        assert_eq!(authoring_skill["sourceMobpack"], "meta_authoring_profiles");

        let samples = catalogs["sample_mobpacks"]
            .as_array()
            .expect("sample mobpacks");
        let sample_skills = samples
            .iter()
            .filter_map(|sample| sample.get("document"))
            .flat_map(|document| document["skill_realms"].as_array().into_iter().flatten())
            .flat_map(|realm| realm["skills"].as_array().into_iter().flatten())
            .collect::<Vec<_>>();
        for skill_id in ["mob.workpad", "mob.review"] {
            let skill = sample_skills
                .iter()
                .find(|skill| skill["id"] == skill_id)
                .unwrap_or_else(|| panic!("missing {skill_id} sample skill"));
            assert_eq!(skill["source"], "inline");
            assert!(
                skill["content"]
                    .as_str()
                    .is_some_and(|content| !content.trim().is_empty())
            );
        }
        let sample_agent_definitions = catalogs["sample_agent_definitions"]
            .as_array()
            .expect("sample agent definitions");
        assert!(sample_agent_definitions.iter().any(|definition| {
            definition["skillDefinitions"]
                .as_array()
                .is_some_and(|skills| skills.iter().any(|skill| skill["id"] == "mob.workpad"))
        }));
    }

    #[test]
    fn sample_skill_realm_requires_real_sample_source_metadata() {
        let samples = json!([
            {
                "id": "missing_source",
                "document": {
                    "skill_realms": [{
                        "id": "realm",
                        "skills": [{ "id": "mob.ghost", "source": "inline", "content": "ghost" }]
                    }]
                }
            },
            {
                "source": "meta/sample-mobpack",
                "document": {
                    "skill_realms": [{
                        "id": "realm",
                        "skills": [{ "id": "mob.no_id", "source": "inline", "content": "ghost" }]
                    }]
                }
            },
            {
                "id": "valid_sample",
                "source": "meta/sample-mobpack",
                "name": "Valid Sample",
                "document": {
                    "skill_realms": [{
                        "id": "realm",
                        "skills": [{ "id": "mob.real", "source": "inline", "content": "real" }]
                    }]
                }
            }
        ]);

        let realm = sample_skill_realm(&samples, true).expect("valid sample realm");
        assert_eq!(realm["source"], "meta/sample-mobpack");
        let skills = realm["skills"].as_array().expect("skills");
        assert_eq!(skills.len(), 1);
        assert_eq!(skills[0]["id"], "mob.real");
        assert_eq!(skills[0]["origin"], "meta/sample-mobpack");
        assert_eq!(skills[0]["sourceMobpack"], "valid_sample");
        assert_eq!(skills[0]["sourceMobpackName"], "Valid Sample");
    }

    #[test]
    fn sample_agent_definitions_require_real_sample_source_metadata() {
        let samples = json!([
            {
                "id": "missing_source",
                "document": {
                    "members": [{
                        "role": "ghost",
                        "name": "Ghost",
                        "profileBinding": "inline",
                        "runtimeMode": "turn_driven",
                        "tools": ["builtins"],
                        "skills": []
                    }]
                }
            },
            {
                "source": "meta/sample-mobpack",
                "document": {
                    "members": [{
                        "role": "no_id",
                        "name": "No ID",
                        "profileBinding": "inline",
                        "runtimeMode": "turn_driven",
                        "tools": ["builtins"],
                        "skills": []
                    }]
                }
            },
            {
                "id": "model_less_sample",
                "source": "meta/sample-mobpack",
                "document": {
                    "members": [{
                        "role": "model_less",
                        "name": "Model Less",
                        "profileBinding": "inline",
                        "runtimeMode": "turn_driven",
                        "tools": ["builtins"],
                        "skills": []
                    }]
                }
            },
            {
                "id": "valid_sample",
                "name": "Valid Sample",
                "source": "meta/sample-mobpack",
                "document": {
                    "members": [{
                        "role": "real",
                        "name": "Real",
                        "model": "gpt-5.5",
                        "profileBinding": "inline",
                        "runtimeMode": "turn_driven",
                        "tools": ["builtins"],
                        "skills": ["mob.real"],
                        "systemPrompt": "Be real."
                    }],
                    "skill_realms": [{
                        "id": "sample",
                        "label": "Sample skills",
                        "source": "meta/sample-mobpack",
                        "skills": [{
                            "id": "mob.real",
                            "label": "Real skill",
                            "source": "inline",
                            "content": "real skill"
                        }]
                    }]
                }
            },
            {
                "id": "second_valid_sample",
                "name": "Second Valid Sample",
                "source": "meta/sample-mobpack",
                "document": {
                    "members": [{
                        "role": "real",
                        "name": "Second Real",
                        "model": "gpt-5.5",
                        "profileBinding": "inline",
                        "runtimeMode": "turn_driven",
                        "tools": ["builtins"],
                        "skills": [],
                        "systemPrompt": "Be independently real."
                    }]
                }
            }
        ]);

        let skill_realms = sample_skill_realm(&samples, true).expect("sample skill realm");
        let definitions = agent_definition_catalog(
            &samples,
            &tool_catalog_response(),
            &json!([skill_realms]),
            "sample",
        );
        let definitions = definitions.as_array().expect("agent definitions");
        assert_eq!(definitions.len(), 2);
        let first = definitions
            .iter()
            .find(|definition| definition["sourceMobpack"] == "valid_sample")
            .expect("valid sample definition");
        let second = definitions
            .iter()
            .find(|definition| definition["sourceMobpack"] == "second_valid_sample")
            .expect("second valid sample definition");
        assert_ne!(first["id"], second["id"]);
        assert_eq!(first["role"], "real");
        assert_eq!(second["role"], "real");
        assert_eq!(first["definitionType"], "meta/profile-member");
        assert_eq!(first["definitionKind"], "sample");
        assert_eq!(first["sourceKind"], "sample");
        assert_eq!(first["source"], "meta/mobpack-profile-member");
        assert_eq!(first["sourceMobpack"], "valid_sample");
        assert_eq!(first["sourceMobpackName"], "Valid Sample");
        assert_eq!(first["sourceOrigin"], "meta/sample-mobpack");
        assert_eq!(first["sourceDocumentPath"], "document.members[0]");
        assert_eq!(second["sourceDocumentPath"], "document.members[0]");
        assert_eq!(first["tools"], json!(["builtins"]));
        assert_eq!(first["toolDefinitions"][0]["id"], "builtins");
        assert_eq!(
            first["toolDefinitions"][0]["source"],
            "meerkat_mob::ToolConfig"
        );
        assert_eq!(first["skills"], json!(["mob.real"]));
        assert_eq!(second["skills"], json!([]));
        assert_eq!(first["skillDefinitions"][0]["id"], "mob.real");
        assert_eq!(
            first["skillDefinitions"][0]["origin"],
            "meta/sample-mobpack"
        );
        assert_eq!(
            first["skillDefinitions"][0]["sourceMobpack"],
            "valid_sample"
        );
    }

