    #[test]
    fn schema_response_commands_match_mobpack_authoring_methods() {
        let schema = mobpack_schema_response();
        let commands = schema["commands"]
            .as_object()
            .expect("schema commands object");
        let expected = BTreeMap::from([
            ("schema", "meta/mobpacks/schema"),
            ("catalogs", "meta/mobpacks/catalogs"),
            ("tools_catalog", "meta/tools/catalog"),
            ("skills_catalog", "meta/skills/catalog"),
            ("agent_definitions", "meta/agent_definitions/list"),
            ("templates", "meta/mobpacks/templates"),
            ("validate", "meta/mobpacks/validate"),
            ("source", "meta/mobpacks/source"),
            ("export", "meta/mobpacks/export"),
            ("import", "meta/mobpacks/import"),
            ("list", "meta/mobpacks/list"),
            ("get", "meta/mobpacks/get"),
            ("create", "meta/mobpacks/create"),
            ("save", "meta/mobpacks/save"),
            ("delete", "meta/mobpacks/delete"),
            ("undo", "meta/mobpacks/undo"),
            ("redo", "meta/mobpacks/redo"),
            ("apply_operation", "meta/mobpacks/apply_operation"),
            ("graph_projection", "meta/mobpacks/graph_projection"),
            ("graph_to_flow", "meta/mobpacks/graph_to_flow"),
            ("deploy_command", "meta/mobpacks/deploy_command"),
            ("deploy_rpc", "meta/mobpacks/deploy"),
            (
                "deploy_cli",
                "rkat mob run <pack.mobpack> --prompt <prompt>",
            ),
        ]);

        assert_eq!(
            commands
                .iter()
                .filter_map(|(key, value)| value.as_str().map(|value| (key.as_str(), value)))
                .collect::<BTreeMap<_, _>>(),
            expected
        );

        let rpc_methods = commands
            .iter()
            .filter(|(key, _)| key.as_str() != "deploy_cli")
            .filter_map(|(_, value)| value.as_str())
            .collect::<BTreeSet<_>>();
        let authoring_methods = crate::rpc::MOBPACK_AUTHORING_METHODS
            .iter()
            .copied()
            .collect::<BTreeSet<_>>();
        assert_eq!(rpc_methods, authoring_methods);
    }

